  /* ===================== 6. SINIF · TEMEL DİNÎ BİLGİLER =====================
     İmam hatip ortaokulunda haftada 1 saatlik ders. Peygamberimizin Hayatı gibi
     dersin TAMAMI bu dosyada: ünite anlatımı (S6'ya eklenir), yıllık takvim
     satırları (CAL6), ana test (Q6.tdb), havuz (H6.tdb) ve ek çalışma seti
     (EKC6.tdb). build.sh'te 08f'den SONRA, 09'dan ÖNCE gelmeli.

     KAYNAK (12 Kasım 2026'da doğrulandı):
     - Okulun kitabı: MEB "Temel Dinî Bilgiler Ders Kitabı (İslam 1)", TTKB kabulü
       03.07.2026, tymm.meb.gov.tr/kitap/533/temel-dini-bilgiler-ders-kitabi-islam-1
       (168 s.). 1. ünite s. 14–47 (1.1 s. 16, 1.2 s. 21, 1.3 s. 28, 1.4 s. 33;
       ünite sonu soruları 41–46). Öğretmenin yazdırdığı 4 soru bu ünitenin 1.1,
       1.2 ve 1.3 bölümleriyle birebir örtüşüyor. Kitabın metni ve soruları
       teliflidir: anlatım ve sorular kendi cümlelerimizle, kitaptan soru KOPYALAMA.
     - TYMM program sayfasında (…/temel-dini-bilgiler-dersi-temel-egitim/18)
       tema listesi YOK ("Kayıt Bulunamadı"); ünite adları kitabın içindekiler
       sayfasından.
     - Sınav kapsamı: Rize İl MEB 2026–2027 konu-soru dağılım tablosu
       (rize.meb.gov.tr/ksdt/temel-egitim/tdb6.pdf, "SINIF: İSLAM 1"). 1. dönem
       1. sınav = 1. ünite, 5 senaryo, 5–7 açık uçlu soru, dört bölümün hepsinden
       (1.4 her senaryoda 1–2 soru). 2. sınav = 2. ünite. Okulun ilinin tablosu
       farklı olabilir; senaryoyu okul seçer. */

  S6.push(
    {key:"tdb", name:"Temel Dinî Bilgiler", color:"var(--s-tdb)", meta:"4 ünite · MEB İslam 1 ders kitabı · haftada 1 saat", lbl:"ÜNİTE",
     note:"Okulun kitabı MEB'in <b>Temel Dinî Bilgiler (İslam 1)</b> ders kitabıdır (2026); ünite ve bölüm adları oradan alındı. İl konu-soru dağılım tablosuna göre (2026–2027, Rize örneği) ortak yazılılar <b>açık uçlu</b> ve kısa cevaplı sorulardan oluşur; çoktan seçmeli, eşleştirme, doğru-yanlış kullanılmaz. <b>1. dönem 1. yazılı</b> 1. ünitenin dört bölümünden 5–7 soru, <b>2. yazılı</b> 2. ünitenin dört bölümünden 5–7 soru içerir. Hangi senaryonun seçildiğini öğretmenden öğren; defterine yazdırdıkları her zaman önceliklidir. Buradaki çoktan seçmeli testler kavramları pekiştirmek içindir.",
     units:[
      {n:"Dinimiz İslam", w:"Eylül–Ekim–Kasım", t:["ÜNİTE 1 · Dinimiz İslam","EK · 1. Yazılı Hazırlık"],
       ogr:[{d:"Kasım 2026", h:
         "<p><b>Sınav çalışma notları</b></p>" +
         "<ol><li><b>Soru:</b> Namazın nasıl kılınacağını öğrenmek isteyen bir öğrenci Hz. Peygamber'in namazla ilgili söz ve davranışlarını araştırmıştır. Bu durum sünnetin İslam dinindeki önemini nasıl gösterir?<br>" +
         "<b>Cevap:</b> Sünnet, Kur'an'da genel olarak bildirilen hükümlerin nasıl uygulanacağını açıklayarak Müslümanlara yol gösterir.</li>" +
         "<li><b>Soru:</b> Bir dağcı zorlu bir yolculuk sırasında Allah'ın (cc) kendisini koruyup gözettiğine inanarak kendisini daha güvende hissetmekte ve karşılaştığı zorluklar karşısında da umudunu korumaktadır. Bu durum inanmanın insan hayatındaki önemini nasıl göstermektedir?<br>" +
         "<b>Cevap:</b> İnanmak insana güven duygusu ve manevi dayanıklılık kazandırır, zorluklar karşısında umudunu korumasına yardımcı olur.</li>" +
         "<li><b>Soru:</b> Ayşe, Allah'ın varlığına ve birliğine kalbiyle inanmakta, Hz. Muhammed'in (sav) Allah'ın elçisi olduğunu diliyle ifade etmektedir. Ayşe inanç bakımından hangi grupta yer alır? Açıklayınız.<br>" +
         "<b>Cevap:</b> Ayşe mümin grubunda yer alır. Çünkü Allah'ın varlığına ve birliğine kalbiyle inanmakta, Hz. Muhammed'in Allah'ın elçisi olduğunu diliyle ifade etmektedir.</li>" +
         "<li><b>Soru:</b> İslam'ın şartı inanç esaslarını yazınız.<br>" +
         "<b>Cevap:</b> Allah'a inanmak, meleklere inanmak, kitaplara inanmak, peygamberlere inanmak, ahiret gününe inanmak, kaza ve kadere inanmak.</li></ol>" +
         "<p><i>4. soru defterde böyle yazılmış, cevabı 6 inanç esası (imanın şartları). Kitapta “İslam'ın şartları” ayrı konudur ve 5 tanedir: kelimeişehadet, namaz, oruç, zekât, hac. Sınavda “inanç esasları / imanın şartları” sorulursa 6'yı, “İslam'ın şartları” sorulursa 5'i yaz.</i></p>"}],
       lead:"Ünite dört bölümdür: <b>1.1</b> Kur'an ve Sünnetin Hayatımdaki Yeri · <b>1.2</b> Niçin İnanıyorum? · <b>1.3</b> Mümin Kimliğim · <b>1.4</b> Allah'ın Güzel İsimleri: Hâdi, Selam, Vekîl. <b>1. yazılı</b> açık uçlu sorulardan oluşur ve il tablosuna göre dört bölümün <b>hepsinden</b> soru gelir. Öğretmenin yazdırdığı dört soru 1.1, 1.2 ve 1.3'ten; defterde olmasa da <b>1.4'ü (Hâdi, Selam, Vekîl) mutlaka çalış</b>. Cevap yazarken kavramı adıyla yaz, sonra olaya bağla: “Bu durum … gösterir, çünkü …”.",
       voc:[["Kur'an","sözlükte “okumak, toplamak, bir araya getirmek”; Hz. Peygamber'e vahiy yoluyla gelen Allah kelamı"],
            ["mushaf","Kur'an'ın kitap hâlinde yazılmış nüshası"],
            ["mucize","Allah'ın izniyle peygamberin elinde gerçekleşen olağanüstü olay; Kur'an en büyük mucizedir"],
            ["sünnet","sözlükte “yol, âdet, gidişat”; Hz. Peygamber'in sözleri, davranışları ve onayları"],
            ["iman","sözlükte “güvenmek, şüphe duymadan kabullenmek, tasdik etmek”"],
            ["tasdik","doğrulama, gerçekliğini kabul etme, gönülden bağlanma"],
            ["fıtrat","insanın yaratılıştan getirdiği inanma ihtiyacı ve iyiliğe yönelimi"],
            ["Amentü","İslam'ın inanç esaslarını sayan dua"],
            ["inanç esasları","Allah'a, meleklere, kitaplara, peygamberlere, ahiret gününe, kader ve kazaya iman (6)"],
            ["salih amel","güzel ve faydalı işler"],
            ["mümin","kalbiyle inanıp diliyle söyleyen kişi"],
            ["kâfir","Allah'ın varlığını ve birliğini, İslam'ın temel esaslarını reddettiğini açıkça söyleyen kişi"],
            ["münafık","kalben inanmadığı hâlde inandığını söyleyen, ikiyüzlü kişi"],
            ["İslam","sözlükte “teslim olmak, güven ve emniyette bulunmak”; son ilahi din"],
            ["kelimeişehadet","“Eşhedü ellâ ilâhe illallah ve eşhedü enne Muhammeden abdühû ve rasûlüh”; İslam'a girişin anahtarı"],
            ["İslam'ın şartları","kelimeişehadet, namaz, oruç, zekât, hac (5)"],
            ["esmayıhüsna","Allah'ın en güzel isimleri (esma: isimler, hüsna: en güzel)"],
            ["Hâdi","doğru yolu gösteren, rehberlik eden"],
            ["Selam","her türlü eksiklikten uzak; güvenlik, barış ve esenlik veren"],
            ["Vekîl","bütün varlıkların işlerini düzenleyen, koruyup gözeten, rızıklara kefil olan"],
            ["hidayet","doğru yola iletme, doğru yolu bulma"],
            ["tevekkül","üzerine düşeni yaptıktan sonra sonucu Allah'a bırakıp O'na güvenme"]],
       p:["<b>Kur'an ve sünnet</b> İslam'ın iki temel kaynağıdır ve birbirini tamamlar: Kur'an Allah'ın emirlerini <b>bildirir</b>, sünnet bu emirlerin <b>nasıl uygulanacağını</b> gösterir.",
          "<b>Kur'an:</b> Hz. Peygamber'e vahiy yoluyla gelen, mushaflarda yazılı, değişmeden günümüze ulaşan ve okunmasıyla ibadet edilen Allah kelamı; son ilahi kitap. İçinde iman, ibadet ve ahlakla ilgili hükümler ve peygamber kıssaları vardır.",
          "Önceki ilahi kitaplar zamanla değiştirildi; Kur'an ise okunarak ve ezberlenerek <b>korundu</b> (Hicr suresi 9). Peygamberimizin <b>en büyük mucizesidir</b>: insanlar ve cinler toplansa benzerini getiremez (İsra suresi 88).",
          "Kur'an'ın rehberliği üç adımla hayata geçer: <b>okumak</b> (ibadettir), <b>anlamak</b>, <b>yaşamak</b>. En önemli adım yaşamaktır. “Sizin en hayırlınız, Kur'an'ı öğrenen ve öğretendir.”",
          "<b>Sünnet:</b> Hz. Peygamber'in <b>sözleri, davranışları</b> ve sahabenin yaptığı uygulamaları <b>onaylaması</b>. Peygamberimiz Müslümanlar için “güzel bir örnek”tir (Ahzab suresi 21).",
          "Kur'an bazı hükümleri <b>genel</b> olarak bildirir; nasıl uygulanacağını <b>sünnet</b> açıklar: namazın nasıl kılınacağı, zekâtın hangi mallardan ne kadar verileceği, haccın uygulanışı, “orta namaz”ın ikindi namazı olduğu.",
          "<b>Niçin inanıyorum?</b> İnsan inanma ihtiyacıyla doğar (<b>fıtrat</b>). İnanmak yalnız olmadığını hissettirir; iç huzuru, güven duygusu ve manevi dayanıklılık verir. Evrendeki düzen bir yaratıcıyı gösterir. İman hayatın anlamını ve ölümden sonrasını açıklar.",
          "<b>İman:</b> kelime olarak güvenmek, şüphe duymadan kabullenmek, tasdik etmek. Dinî anlamı: inanılması gerekenleri <b>kalp ile tasdik edip dil ile söylemek</b>.",
          "<b>İnanç esasları (6)</b> Amentü duasında toplanır: Allah'a, meleklere, kitaplara, peygamberlere, ahiret gününe, kader ve kazaya iman. Birbirinden ayrılmaz bir bütündür; birine inanmamak imanın bütünlüğünü bozar.",
          "İman ile <b>salih amel</b> (güzel ve faydalı işler) bir ağacın <b>kökü ve dalları</b> gibidir: iman davranışlarla beslenip olgunlaşır.",
          "İnanç bakımından üç grup vardır: <b>mümin</b> (kalbiyle inanır, diliyle söyler) · <b>kâfir</b> (reddettiğini açıkça söyler) · <b>münafık</b> (inanmadığı hâlde inandığını söyler).",
          "<b>Kelimeişehadet</b> İslam'a girişin anahtarıdır. <b>İslam'ın şartları (5)</b>: kelimeişehadet getirmek, namaz kılmak, oruç tutmak, zekât vermek, hacca gitmek. Bir binayı ayakta tutan sütunlar gibidir.",
          "Mümin ibadetlerini ahlakına yansıtır: dürüst, adaletli, nazik, sorumluluk sahibi ve <b>güvenilir</b>dir. “Müminlerin iman bakımından en mükemmeli, ahlak bakımından en güzel olanıdır.”",
          "<b>Esmayıhüsna:</b> Allah'ın en güzel isimleri (doksan dokuz). <b>Hâdi</b> doğru yolu gösteren · <b>Selam</b> eksiklikten uzak, esenlik ve güven veren · <b>Vekîl</b> işleri düzenleyen, koruyup gözeten. <b>Tevekkül</b> Vekîl ismiyle ilgilidir."],
       box:[{t:"Açık uçlu soruya cevap kalıbı", h:"<ol><li><b>Kavramı adıyla yaz:</b> sünnet, iman, mümin, münafık, tevekkül, Hâdi…</li><li><b>Tanımını ekle:</b> “Sünnet, Kur'an'da genel olarak bildirilen hükümlerin nasıl uygulanacağını açıklar.”</li><li><b>Olaya bağla:</b> “Bu durum … gösterir, çünkü …”. Soruda bir kişi ya da olay varsa cevapta mutlaka ona dön.</li><li><b>Biliyorsan destekle:</b> bir ayet ya da hadis (“Kalpler ancak Allah'ı anmakla huzur bulur.”).</li></ol><p>Öğretmenin dört sorusu bu kalıpta: önce durum anlatılıyor, sonra “bu durum neyi gösterir?” diye soruluyor.</p>"},
            {t:"Kur'an ve sünnet — kim ne yapar?", h:"<ul><li><b>Kur'an-ı Kerim:</b> Rabbimizin gönderdiği <b>son ilahi kitap</b>. İnsanların neye inanacağını, nasıl ibadet edeceğini, nasıl bir ahlaka sahip olacağını, toplum hayatını nasıl düzenleyeceğini bildirir. “... De ki: O, inananlar için doğru yolu gösteren bir kılavuzdur...” (Fussilet suresi 44)</li><li><b>Sünnet:</b> Peygamberimizin Kur'an'ı nasıl anlayıp kendi hayatında nasıl yaşadığını gösterir. Kur'an'da Peygamberimize, kendisine indirileni insanlara <b>açıklama</b> görevi verildiği bildirilir (Nahl suresi 44) ve “Kim Peygamber'e itaat ederse Allah'a itaat etmiş olur...” buyrulur (Nisa suresi 80).</li><li><b>Görev paylaşımı:</b> Kur'an emri bildirir → sünnet uygulamayı gösterir. İkisine birlikte uyan Müslüman dinini doğru öğrenir, hayatını buna göre düzenler; dünyada ve ahirette mutluluğa ulaşır.</li><li><b>Peygamberimizin örnek davranışları:</b> işe besmeleyle başlamak, temizliğe dikkat etmek, israftan kaçınmak, büyüklere saygı, küçüklere şefkat, anne babaya iyilik, selamlaşmak; her koşulda adaletli ve doğru sözlü olmak.</li></ul>"},
            {t:"Niçin inanıyorum? — beş cevap", h:"<ol><li><b>Fıtrat:</b> İnsan, yüce bir varlığa inanma ve ona sığınma ihtiyacıyla doğar. Peygamberimiz: “Her doğan çocuk fıtrat üzere doğar...”</li><li><b>Huzur ve güven:</b> İnanmak insana yalnız olmadığını hissettirir; <b>iç huzuru, güven duygusu</b> ve <b>manevi dayanıklılık</b> kazandırır, zor anlarda umudu korur. “... Biliniz ki kalpler ancak Allah'ı anmakla huzur bulur.” (Rad suresi 28)</li><li><b>Evrendeki düzen:</b> Yıldızlardan gözle göremediğimiz varlıklara kadar her şey bir yaratıcıyı gösterir. Kupkuru toprağın baharda çiçeklenmesi tesadüf değildir: “Allah'ın rahmetinin izlerine bir bak: Ölü toprağa nasıl can veriyor...” (Rum suresi 50)</li><li><b>Hayatın anlamı:</b> İman, ölümün bir son değil asıl hayatın başlangıcı olduğunu öğretir; “Dünyaya neden geldik, ölümden sonra bizi ne bekliyor?” sorularına cevap verir.</li><li><b>Sevgi ve nimetler:</b> İnsanlar arasındaki sevgi ve merhamet de Allah'ın varlığının delillerindendir (Rum suresi 21). Bizi yaratan, yaşatan ve nimetleriyle kuşatan Rabbimize iman eder, O'na şükrederiz.</li></ol>"},
            {t:"İnanç esasları (6) ile İslam'ın şartları (5) — karıştırma!", h:"<p><b>İslam'ın inanç esasları</b> (imanın şartları da denir) — <b>6</b>: <b>1</b> Allah'a iman · <b>2</b> Meleklere iman · <b>3</b> Kitaplara iman · <b>4</b> Peygamberlere iman · <b>5</b> Ahiret gününe iman · <b>6</b> Kader ve kazaya iman.</p><p><b>Amentü</b> (okunuşu; sınavda anlamını bilmen yeter): “Âmentü billâhi ve melâiketihî ve kütübihî ve rusülihî velyevmilâhiri ve bilkaderi hayrihî ve şerrihî minallâhi teâlâ. Velba‘sü ba‘delmevti hakkun. Eşhedü ellâ ilâhe illallâh ve eşhedü enne Muhammeden abdühû ve rasûlüh.”<br><i>Anlamı:</i> Allah'a, meleklerine, kitaplarına, peygamberlerine, ahiret gününe, kadere, hayır ve şerrin Allah'tan olduğuna iman ettim. Ölümden sonra diriliş gerçektir. Allah'tan başka ilah olmadığına, Muhammed'in O'nun kulu ve elçisi olduğuna şehadet ederim.</p><p><b>İslam'ın şartları</b> — <b>5</b>: <b>1</b> Kelimeişehadet getirmek · <b>2</b> Namaz kılmak · <b>3</b> Oruç tutmak · <b>4</b> Zekât vermek · <b>5</b> Hacca gitmek. Peygamberimiz: “İslam beş esas üzerine kurulmuştur...”</p><p><b>Ayırt etme ipucu:</b> İnanç esaslarının hepsi “… <b>iman</b>” diye biter, kalple kabul edilir. İslam'ın şartları ise <b>yapılan</b> işlerdir: bir söz (kelimeişehadet) ve dört ibadet.</p>"},
            {t:"Mümin kimliği — ibadet ve ahlak", h:"<ul><li><b>Mümin olmak:</b> İslam'ın çağrısını özgür iradesiyle kabul edip Allah'ın var ve bir olduğunu söylemek. Anahtar <b>kelimeişehadet</b>tir: “Ben şehadet ederim ki Allah'tan başka ilah yoktur. Yine şehadet ederim ki Hz. Muhammed, Allah'ın kulu ve resulüdür.”</li><li><b>Namaz:</b> Akıllı ve ergenlik çağına gelmiş her müminin günde beş vakit kılması gereken farz ibadet. Zamanı planlı kullanmayı ve disiplini öğretir; “... Muhakkak ki namaz, hayâsızlıktan ve kötülükten alıkoyar...” (Ankebut suresi 45)</li><li><b>Oruç:</b> Ramazan ayında gün boyunca yemekten, içmekten ve orucu bozan şeylerden uzak durmak. İradeye hâkim olmayı, sabrı, hâlden anlamayı ve merhameti öğretir.</li><li><b>Zekât:</b> Zengin sayılan Müslümanın her yıl malından belli bir payı ihtiyaç sahiplerine vermesi. Paylaşma ve dayanışmayı güçlendirir, bencilliği yok eder.</li><li><b>Hac:</b> Gücü yeten Müslümanın, zilhicce ayının belli günlerinde ibadet için Kâbe'ye ve çevresindeki kutsal yerlere gitmesi. Farklı dil ve kültürden Müslümanları kardeşlik, birlik ve beraberlik içinde buluşturur.</li><li><b>Ahlak:</b> Mümin; doğruluk, adalet, nezaket ve sorumluluk bilincini kişiliğinin parçası yapar. “Müslüman, dilinden ve elinden insanların selamette olduğu kişidir. Mümin ise insanların canları ve malları konusunda kendisinden emin oldukları kişidir.”</li></ul>"},
            {t:"Tevekkül: önce çalış, sonra güven", h:"<p><b>Tevekkül</b>, insanın sorumluluklarını yerine getirdikten sonra sonucu Allah'a bırakması ve O'na güvenmesidir. Kur'an: “... Kararını verdiğin zaman da artık Allah'a dayanıp güven. Çünkü Allah, kendisine dayanıp güvenenleri sever.” (Al-i İmran suresi 159)</p><p>Peygamberimiz, gereği gibi tevekkül edenlerin, sabah aç çıkıp akşam tok dönen <b>kuşlar</b> gibi rızıklandırılacağını söylemiştir. Kuşlar yuvada beklemez, rızık için uçar: önce çaba, sonra güven.</p><p><i>Ek bilgi:</i> Mehmet Akif Ersoy'un dizeleri: “Allah'a dayan, sa'ye sarıl, hikmete râm ol... / Yol varsa budur, bilmiyorum başka çıkar yol.” (sa'y: çalışıp çabalama)</p><p>Çalışmadan “Allah nasılsa verir.” demek tevekkül <b>değildir</b>.</p>"}],
       tbl:[{h:["Kur'an'da (genel hüküm)","Sünnette (nasıl uygulanacağı)"], r:[
              ["Namaz kılmak farzdır.","Nasıl kılınacağı, vakitleri ve rekât sayıları. “Beni nasıl namaz kılıyor gördüyseniz siz de namazı öyle kılınız.”"],
              ["Zengin Müslümanlar zekât vermelidir.","Hangi mallardan ne kadar zekât verileceği"],
              ["Hac farzdır.","Zamanı, şartları ve uygulanışı. “Hacda yapacağınız ibadetleri benden öğrenin...”"],
              ["“Namazları ve orta namazı aksatmadan kılın...”","“Orta namaz, ikindi namazıdır.”"]]},
            {h:["Grup","Kalbiyle","Diliyle","Kısaca"], r:[
              ["<b>Mümin</b>","inanır","söyler","Allah'ın varlığını, birliğini ve Hz. Muhammed'in O'nun kulu ve elçisi olduğunu kalbiyle onaylayıp diliyle söyleyen"],
              ["<b>Münafık</b>","inanmaz","“inanıyorum” der","İkiyüzlü; inancında samimi değil. Alametleri: konuşunca yalan söyler, emanete ihanet eder, sözünde durmaz."],
              ["<b>Kâfir</b>","inanmaz","reddettiğini açıkça söyler","Gerçeği bile bile reddeden"]]},
            {h:["İsim","Anlamı","Ayet / dua","Hayatımıza yansıması"], r:[
              ["<b>Hâdi</b>","İnsanlara doğru yolu gösteren, rehberlik eden; zihinleri ve gönülleri aydınlatan","“Bizi dosdoğru yola ilet.” (Fatiha suresi 6) · “... Hiç şüphe yok ki Allah iman edenleri doğru yola iletir.” (Hac suresi 54)","Doğruyu öğrenmek için Kur'an'a ve Peygamberimizin rehberliğine yönelmek; hidayet için dua etmek"],
              ["<b>Selam</b>","Her türlü eksiklikten uzak, yaratmasında kusursuz; kullarına güvenlik, barış, esenlik ve sağlık veren","Peygamberimiz namazdan sonra: “Allah'ım! Sen Selam'sın, selamet sendendir...”","Selamlaşmak, çevresine güven vermek, kimseye zarar vermemek. “Selamünaleyküm” = “Allah sana sağlık, afiyet, esenlik, güven ve huzur versin.”"],
              ["<b>Vekîl</b>","Bütün varlıkların işlerini düzenleyen, koruyup gözeten, kullarının rızıklarına kefil olan","“... Kim Allah'a dayanıp güvenirse Allah ona yeter...” (Talak suresi 3) · “... Allah bize yeter, O ne güzel vekildir...”","Üzerine düşeni yaptıktan sonra sonucu Allah'a bırakmak (tevekkül)"]]},
            {h:["Durum","Kavram / isim"], r:[
              ["Namazın nasıl kılınacağını Peygamberimizin söz ve davranışlarından öğrenmek","Sünnet: Kur'an'daki hükmün nasıl uygulanacağını açıklar."],
              ["Zor bir anda Allah'ın kendisini koruduğuna inanıp umudunu korumak","İnanmanın kazandırdığı güven duygusu ve manevi dayanıklılık"],
              ["Doğadaki düzene bakıp bir yaratıcı olduğunu düşünmek","Niçin inanıyorum? Evrendeki deliller."],
              ["İnsanın doğuştan yüce bir varlığa inanma ihtiyacı","Fıtrat"],
              ["İnancını güzel davranışlarla göstermek","İman ve salih amel"],
              ["Kalbiyle inanıp diliyle söylemek","Mümin"],
              ["İnanmadığı hâlde “inanıyorum” demek","Münafık"],
              ["Doğruyu bulmak için dua etmek, rehberlik aramak","Hâdi"],
              ["Selamlaşmak, kimseye zarar vermemek","Selam"],
              ["Elinden geleni yapıp sonucu Allah'a bırakmak","Vekîl · tevekkül"]]},
            {h:["Bölüm (1. yazılı)","S1","S2","S3","S4","S5"], r:[
              ["1.1 Kur'an ve Sünnetin Hayatımdaki Yeri","1","1","3","2","1"],
              ["1.2 Niçin İnanıyorum?","3","2","1","1","1"],
              ["1.3 Mümin Kimliğim","1","1","1","1","2"],
              ["1.4 Hâdi, Selam, Vekîl","2","1","2","2","2"],
              ["<b>Toplam</b>","7","5","7","6","6"]]}],
       trap:"<b>İnanç esasları (6) ile İslam'ın şartlarını (5) karıştırmak.</b> Melekler, kitaplar, peygamberler, ahiret, kader ve kaza <b>inanç esasıdır</b>; kelimeişehadet, namaz, oruç, zekât ve hac <b>İslam'ın şartıdır</b>. İkinci tuzak: münafık ile kâfiri karıştırmak. Kâfir inanmadığını açıkça söyler, münafık inanmadığı hâlde “inanıyorum” der. Üçüncüsü: sünneti yalnız Peygamberimizin sözleri sanmak. Sünnet söz, davranış ve onaydır. Dördüncüsü: tevekkülü “çalışmadan beklemek” sanmak. Önce çalışılır, sonra Allah'a güvenilir.",
       q:["Kur'an ve sünnet İslam'ın iki temel kaynağıdır. Bu iki kaynak birbirini nasıl tamamlar? Bir örnekle açıkla.",
          "Sünnet ne demektir? Sözlük anlamını ve dinî terim anlamını yaz.",
          "Zekât vermek isteyen bir kişi, hangi mallardan ne kadar zekât vereceğini öğrenmek için Peygamberimizin uygulamalarını araştırıyor. Bu durum sünnetin İslam dinindeki önemini nasıl gösterir?",
          "Kur'an-ı Kerim'i önceki ilahi kitaplardan ayıran özellik nedir? Bunu bildiren ayeti yaz.",
          "Kur'an neden Peygamberimizin en büyük mucizesidir?",
          "Kur'an'ın hayatımıza yön vermesi için ne yapmamız gerekir? Üç adımı yaz.",
          "Uzun süredir hastanede yatan Murat Bey, Allah'ın kendisini yalnız bırakmayacağına inanıyor; bu sayede sabırlı ve umutlu kalabiliyor. Bu durum inanmanın insan hayatındaki önemini nasıl gösterir?",
          "İnsan neden inanma ihtiyacı duyar? “Fıtrat” kavramını kullanarak açıkla.",
          "Baharda kupkuru toprağın yeşermesi ya da küçücük bir arının bal yapması sana neyi düşündürür? “Niçin inanıyorum?” sorusunu bu örnekle cevapla.",
          "İman ne demektir? Kelime anlamını ve dinî anlamını yaz.",
          "İslam'ın inanç esaslarını (imanın şartlarını) yaz. Bunlardan birine inanmamak imanı nasıl etkiler?",
          "İman ile salih amel arasındaki ilişkiyi kitaptaki benzetmeyle açıkla.",
          "Bir kişi, Müslümanların yanında “Ben de inanıyorum.” diyor ama kalbinden inanmıyor. Bu kişi inanç bakımından hangi grupta yer alır? Açıkla.",
          "İnsanlar inanç bakımından kaç gruba ayrılır? Her grubu tanımla.",
          "Bir kişi Müslüman olduğunu hangi sözle ifade eder? Bu sözün anlamını yaz.",
          "İslam'ın şartlarını yaz. Bunlardan ikisinin müminin hayatına katkısını açıkla.",
          "Peygamberimiz “Müslüman, dilinden ve elinden insanların selamette olduğu kişidir.” buyurmuştur. Bu hadise göre mümin kimliğine uygun iki davranış yaz.",
          "Esmayıhüsna ne demektir? Hâdi, Selam ve Vekîl isimlerinin anlamlarını yaz.",
          "Bir futbol takımı maça haftalarca hazırlanıyor. Maçtan önce kaptan “Biz elimizden geleni yaptık, sonucu Allah'a bırakıyoruz.” diyor. Bu tutum Allah'ın hangi ismiyle ve hangi kavramla ilgilidir? Açıkla.",
          "Allah'ın Selam ismini bilen bir Müslüman insanlara nasıl davranır? İki örnek ver.",
          "Namazda okunan Fatiha suresindeki “Bizi dosdoğru yola ilet.” ayeti Allah'ın hangi ismiyle ilgilidir? Neden?"],
       a:["Kur'an-ı Kerim Allah'ın emirlerini <b>bildirir</b>; sünnet bu emirlerin <b>nasıl uygulanacağını</b> gösterir. Örnek: Kur'an namazın farz olduğunu bildirir; namazın nasıl kılınacağını, vakitlerini ve rekât sayılarını Peygamberimizin sünnetinden öğreniriz.",
          "Sözlükte <b>yol, âdet, gidişat</b> demektir. Dinî terim olarak Hz. Peygamber'in <b>sözleri</b>, <b>davranışları</b> ve sahabenin yaptığı uygulamaları <b>onaylaması</b>dır.",
          "Kur'an'da zekâtın farz olduğu bildirilmiş, ayrıntısı verilmemiştir. Sünnet, Kur'an'da <b>genel olarak bildirilen hükümlerin nasıl uygulanacağını açıklayarak</b> Müslümanlara yol gösterir. Ayrıntıyı öğrenmek için bu yüzden sünnete başvururuz. Aynısı namaz ve hac için de geçerlidir.",
          "Önceki ilahi kitaplar zamanla insanlar tarafından değiştirildi, asıl metinleri günümüze ulaşmadı. Kur'an ise okunarak ve ezberlenerek korundu, <b>hiç değişmeden</b> günümüze ulaştı. Ayet: “Şüphesiz o zikri (Kur'an'ı) biz indirdik biz! Onun koruyucusu da elbette biziz.” (Hicr suresi 9)",
          "Çünkü Kur'an'ın, insanların ortaya koyamayacağı bir <b>üslubu ve anlam bütünlüğü</b> vardır. İsra suresi 88. ayette, insanlar ve cinler bir araya gelip birbirine destek olsalar bile Kur'an'ın <b>bir benzerini getiremeyecekleri</b> bildirilir.",
          "<b>Okumak</b> (Kur'an okumak ibadettir), <b>anlamak</b> (ayetler üzerinde düşünüp mesajını kavramak) ve <b>yaşamak</b> (öğrendiklerini günlük hayata geçirmek). En önemli adım yaşamaktır.",
          "İnanmak insana <b>güven duygusu</b>, <b>iç huzuru</b> ve <b>manevi dayanıklılık</b> kazandırır. İnsan kendini yalnız hissetmez, zorluklar karşısında <b>umudunu korur</b>. Ayet: “... Biliniz ki kalpler ancak Allah'ı anmakla huzur bulur.” (Rad suresi 28)",
          "<b>Fıtrat</b>, insanın yaratılıştan getirdiği inanma ihtiyacı ve iyiliğe yönelimidir. Her insan Allah'ın varlığını ve birliğini kabul etme eğilimiyle doğar; bu yüzden yüce bir varlığa inanma ve ona sığınma ihtiyacı duyar. Peygamberimiz “Her doğan çocuk fıtrat üzere doğar...” buyurmuştur.",
          "Bu düzen ve güzellikler <b>tesadüf olamaz</b>, her şey bir <b>yaratıcının varlığını</b> gösterir. Kur'an'da “Allah'ın rahmetinin izlerine bir bak: Ölü toprağa nasıl can veriyor...” (Rum suresi 50) buyrulur. Bizi yaratan, yaşatan ve sayısız nimet veren Rabbimize bu yüzden inanır, O'na şükrederiz.",
          "Kelime olarak <b>güvenmek, şüphe duymadan kabullenmek, tasdik etmek</b>. Dinî anlamı: Allah'a ve inanılması gereken bütün esaslara <b>kalp ile inanıp (tasdik edip) bunu dil ile söylemek</b>.",
          "Allah'a iman, meleklere iman, kitaplara iman, peygamberlere iman, ahiret gününe iman, kader ve kazaya iman (<b>6</b>). Bu esaslar birbirini tamamlayan, ayrılmaz bir bütündür; birine inanmamak <b>imanın bütünlüğünü bozar</b>.",
          "<b>Salih amel</b> güzel ve faydalı işlerdir. İman ile amel bir <b>ağacın kökü ile dalları</b> gibidir: kök ne kadar sağlamsa dallar da o kadar canlı olur. İman güzel davranışlarla beslenip olgunlaşır; davranışlarla beslenmeyen iman zayıflayabilir. Kur'an'da iman ve salih amel birçok yerde yan yana anılır.",
          "<b>Münafık</b> grubunda yer alır. Çünkü Allah'ın varlığına ve birliğine <b>kalben inanmadığı hâlde</b> inandığını <b>söylüyor</b>, ikiyüzlü davranıyor. Mümin olsaydı hem kalbiyle inanır hem diliyle söylerdi.",
          "<b>Üç</b> gruba ayrılır. <b>Mümin:</b> kalbiyle inanıp diliyle söyleyen kişi. <b>Kâfir:</b> İslam'ın temel esaslarını, Allah'ın varlığını ve birliğini reddettiğini açıkça söyleyen kişi. <b>Münafık:</b> kalben inanmadığı hâlde inandığını söyleyen, ikiyüzlü kişi.",
          "<b>Kelimeişehadet</b> ile: “Eşhedü ellâ ilâhe illallah ve eşhedü enne Muhammeden abdühû ve rasûlüh.” Anlamı: “Ben şehadet ederim ki Allah'tan başka ilah yoktur. Yine şehadet ederim ki Hz. Muhammed, Allah'ın kulu ve resulüdür.”",
          "Kelimeişehadet getirmek, namaz kılmak, oruç tutmak, zekât vermek, hacca gitmek (<b>5</b>). Katkılara örnek: <b>Namaz</b> zamanı planlı kullanmayı ve disiplini öğretir, kötülükten alıkoyar. <b>Oruç</b> iradeye hâkim olmayı, sabrı ve hâlden anlamayı öğretir. <b>Zekât</b> paylaşmayı ve yardımlaşmayı geliştirir, bencilliği yok eder. <b>Hac</b> Müslümanlar arasında kardeşlik ve birlik duygusunu güçlendirir. (İkisini yazman yeterli.)",
          "Örnekler: kimseye kırıcı söz söylememek, yalan söylememek, kimsenin eşyasına zarar vermemek, emanete sahip çıkmak, hata yapınca sorumluluk alıp özür dilemek. (Sözle ve davranışla kimseye zarar vermemeyi gösteren iki örnek yeterli.)",
          "Allah'ın <b>en güzel isimleri</b> demektir (esma: isimler, hüsna: en güzel). <b>Hâdi:</b> insanlara doğru yolu gösteren, rehberlik eden. <b>Selam:</b> her türlü eksiklikten uzak; kullarına güvenlik, barış ve esenlik veren. <b>Vekîl:</b> bütün varlıkların işlerini düzenleyen, koruyup gözeten, kullarının rızıklarına kefil olan.",
          "<b>Vekîl</b> ismiyle ve <b>tevekkül</b> kavramıyla ilgilidir. Tevekkül, sorumluluklarını yerine getirdikten sonra sonucu Allah'a bırakıp O'na güvenmektir. Takım önce çalışmış, sonra Allah'a güvenmiştir; çalışmadan beklemek tevekkül olmazdı.",
          "Çevresine güven verir, kimseye zarar vermez, insanlarla iyi ilişkiler kurar. Örnekler: karşılaştığı kişiye “Selamünaleyküm.” der; kendisine verilen selamı aynısıyla ya da daha güzeliyle alır; kırıcı davranmaz, sözüyle ve eliyle kimseyi incitmez. (“Selamünaleyküm – Aleykümselam” = “Allah sana sağlık, afiyet, esenlik, güven ve huzur versin.”)",
          "<b>Hâdi</b> ismiyle ilgilidir. Hâdi, doğru yolu gösteren ve rehberlik eden demektir. Bu ayetle Allah'tan <b>hidayet</b> isteriz, yani doğru yolu bulmak için yardım dileriz. Bu isteği namazın her rekâtında yenileriz."]},

      {n:"Hayatımız İbadet", w:"Kasım–Aralık–Ocak", t:["ÜNİTE 2 · Hayatımız İbadet","EK · 2. Yazılı Hazırlık"],
       lead:"Ünite dört bölümdür: <b>2.1</b> Allah'a Yaklaşmanın Yolu: İbadet · <b>2.2</b> İbadetin Temel İlkeleri · <b>2.3</b> Hükümlerine Göre İbadetler · <b>2.4</b> Allah'ın Güzel İsimleri: Rakib, Şekur, Hamid. 1. dönem <b>2. yazılı</b> bu üniteden gelir. İl tablosuna göre (Rize örneği) 5–7 açık uçlu soru dört bölümün <b>hepsinden</b> sorulur: 2.1 ve 2.2'den 1–2'şer, 2.3'ten her senaryoda 1, 2.4'ten 1–2 soru. Cevapta kavramı adıyla yaz (niyet, ihlas, farz, vacip, Şekur…), sonra olaya bağla: “Bu davranış … gösterir, çünkü …”.",
       p:["<b>İbadet:</b> Allah'ın emrettiği ve insanın O'na karşı yapmakla yükümlü olduğu davranışlardır. Allah'ı yüceltmek ve övmek, O'na boyun eğmek, itaat ve saygı göstermek, kulluk etmek demektir. Allah'ın razı olacağı her davranış, duygu ve düşünce ibadettir.",
          "İbadet, kulun Rabbine bağlılığını gösterip O'na <b>yaklaşma</b> çabasıdır ve <b>yalnız Allah için</b> yapılır. İnsanın yaratılış amacı Allah'a ibadettir: “Ben cinleri ve insanları, ancak bana ibadet etsinler diye yarattım.” (Zariyat suresi 56) Gökte ve yerde ne varsa kendi diliyle Allah'ı tespih eder.",
          "<b>İman ile ibadet</b> arasında güçlü bir bağ vardır. İbadet, iman esaslarından hemen sonra gelir ve imanın <b>göstergesidir</b>. İman ibadetlerle kalbe yerleşip güçlenir, ibadet de imanla anlam kazanır. “... De ki: Şüphesiz benim namazım da diğer ibadetlerim de yaşamam da ölümüm de âlemlerin Rabbi Allah içindir.” (Enam suresi 162)",
          "<b>İbadetin amacı:</b> asıl gaye <b>Allah'ın rızasını kazanmaktır</b>. İbadet Allah'a şükrün, hamdin, itaatin, kulluğun ve bağlılığın ifadesidir. <b>Hamt</b> “Allah'ı övmek, yüceltmek, O'na şükretmek”, <b>kulluk</b> ise Allah'ın “Yap!” dediğini yapıp “Yapma!” dediğinden uzak durmaktır.",
          "<b>Salih amel:</b> Allah rızası için yapıldığında ibadet sayılan iyi, doğru ve faydalı iş ve davranışlardır (salih: iyi, doğru, faydalı · amel: iş). Namaz, oruç, zekât gibi ibadetler de tebessüm etmek, ağaç dikmek, selamlaşmak, yardım etmek, hayvanlara merhamet göstermek de salih ameldir. Bir iyiliğin salih amel sayılması için yapanın <b>mümin</b> olması gerekir.",
          "<b>Vakti ve şartları belirlenmiş ibadetler:</b> namaz, oruç, fıtır sadakası (fitre), zekât, hac ve kurban. Bunların vakti ile şekil ya da miktar gibi şartları dinimizce belirlenmiştir. Namaz bütün ibadetlerin <b>özü</b> sayılır. Peygamberimiz amellerin en üstününün vaktinde kılınan namaz olduğunu söylemiştir.",
          "<b>Vakti ve şartları belirlenmemiş ibadetler</b> belli bir şekle, şarta ve vakte bağlı değildir: dua etmek, Kur'an okuyup anlamaya çalışmak, Allah'ı anmak ve tespih etmek. Güler yüz, doğayı ve canlıları korumak, temizlik, sabır, ilim öğrenmek, helal rızık için çalışmak, alışverişte dürüstlük, sadaka, anne babaya iyilik, akraba ziyareti, komşuluk hakkı ve misafire ikram da Allah rızasına uygun olduğu için ibadettir.",
          "<b>İbadetin insana kazandırdıkları:</b> İnsan yaratılış amacını fark eder, hayatı anlam kazanır, kendini güvende ve huzurlu hisseder, kötülüklerden uzak durur. <b>Namaz</b> düzenli yaşamayı, <b>abdest</b> temizliği (ve günahlardan arınmayı), <b>oruç</b> açlık ve susuzluğa karşı sabrı, <b>kurban</b> sevilen şeylerden fedakârlığı öğretir. <b>Zekât, fitre ve sadaka</b> her şeyin asıl sahibinin Allah olduğunu hatırlatıp paylaşmaya teşvik eder.",
          "<b>Topluma katkısı:</b> Cemaatle kılınan namaz Müslümanları camide buluşturup kaynaştırır. Hacda dünyanın her yerinden gelen Müslümanlar arasında dil, ırk ve renk ayrımı kalkar. Zekât, fitre ve kurban zenginle fakir arasında <b>köprü</b> olur, ekonomik ve sosyal adaletsizliği önler, dayanışmayı güçlendirir.",
          "<b>İbadetin temel ilkeleri</b> (kabul şartları) dörttür: <b>iman</b> (iyi davranışın ibadet sayılmasının ilk şartı), <b>niyet</b> (hangi ibadeti yapacağına karar verip onu Allah için yapmak), <b>ihlas</b> (yalnız Allah'ın rızasını gözetmek, gösterişten uzak durmak), <b>sünnete uygunluk</b> (ibadeti Peygamberimizin öğrettiği şekilde yapmak).",
          "Dört ilke birbirini <b>tamamlar</b>, biri eksik olursa ibadet amacına ulaşmaz. İbadetlerin vakti, şekli ve şartları Allah ve Peygamberimiz tarafından konmuştur, kimse değiştiremez. “... Allah katında amellerin en sevimlisi, az da olsa devamlı olanıdır.” İbadetini sürdüren kişinin disiplin ve sorumluluk duygusu gelişir.",
          "<b>Mükellef:</b> akli dengesi yerinde ve ergenlik çağına ulaşmış, dinî sorumluluk taşıyan kişidir. Allah'ın emirlerinden, yasaklarından ve ibadetlerden sorumludur. İbadetler hükümlerine göre dörde ayrılır: <b>farz, vacip, sünnet, müstehap</b>.",
          "<b>Farz</b> Allah'ın kesin emri (beş vakit namaz, ramazan orucu, zekât, hac) · <b>vacip</b> farz kadar kesin olmasa da emredilen (kurban, fitre, bayram ve vitir namazı) · <b>sünnet</b> Peygamberimizin farz ve vacip dışında yapıp bize tavsiye ettiği (teravih, sadaka, selamlaşmak, suyu üç yudumda içmek) · <b>müstehap</b> yapılması hoş karşılanan ama zorunlu tutulmayan (nafile namaz ve oruç).",
          "<b>Rakib</b> her işi ve her varlığı daima gözetip koruyan · <b>Şekur</b> kullarının iyiliklerine bol karşılık veren, az amele çok mükâfat veren · <b>Hamid</b> övgüye layık olan, övülen ve öven. “Elhamdülillah” “Her türlü övgü Allah'a mahsustur.” demektir."],
       box:[{t:"Açık uçlu soruya cevap kalıbı", h:"<ol><li><b>Kavramı adıyla yaz:</b> ibadet, salih amel, niyet, ihlas, farz, vacip, Rakib…</li><li><b>Tanımını ekle:</b> “İhlas, ibadette yalnız Allah'ın rızasını gözetmektir.”</li><li><b>Olaya bağla:</b> Soruda bir kişi ya da olay varsa cevapta mutlaka ona dön: “Bu davranış … ilkesine örnektir, çünkü …”.</li><li><b>Karşılaştırma sorusunda</b> (farz–vacip, sünnet–müstehap) <b>benzerliği</b> ve <b>farkı</b> ayrı cümlelerle yaz, her hükme bir örnek ekle.</li><li><b>Esma sorusunda</b> önce ismin anlamını yaz, sonra bu ismi bilen bir Müslümanın nasıl davrandığını söyle.</li></ol>"},
            {t:"İbadetin amacı: beş anahtar kelime", h:"<p>Kitaptaki bilgi görseline göre ibadetin amacı <b>şükretmek</b>, <b>hamdetmek</b>, Allah'a <b>itaat etmek</b>, <b>kulluk etmek</b> ve O'na <b>bağlılıktır</b>. Hepsinin özünde <b>Allah'ın rızasını kazanmak</b> vardır.</p><ul><li><b>Şükür:</b> Sayısız nimet veren Rabbimize teşekkür etmek. “... Yalnız Allah'a ibadet et ve şükredenlerden ol!” (Zümer suresi 66)</li><li><b>Hamt:</b> Allah'ı övmek, yüceltmek, O'na şükretmek.</li><li><b>Kulluk ve itaat:</b> Allah'ın “Yap!” dediğini yapmak, “Yapma!” dediğinden uzak durmak. Kulluğun en önemli göstergesi ibadetlerdir. “Ey insanlar! Sizi ve sizden öncekileri yaratan Rabbinize ibadet edin...” (Bakara suresi 21)</li><li><b>Yaratılış amacı:</b> “Ben cinleri ve insanları, ancak bana ibadet etsinler diye yarattım.” (Zariyat suresi 56)</li></ul>"},
            {t:"İbadetin dört temel ilkesi (kabul şartları)", h:"<ol><li><b>İman:</b> İyi bir kul olmanın ilk şartı Allah'ın varlığına ve birliğine inanmaktır. İman olmadan yapılan iyilik ibadet değeri kazanmaz. “(Fakat) iman edip salih ameller işleyenlere gelince Rableri onları imanları sebebiyle hidayete erdirir...” (Yunus suresi 9)</li><li><b>Niyet:</b> Hangi ibadeti yapacağına karar verip onu Allah için yapmak. Kalple yapılır, dille de söylenir. Niyetsiz ibadet geçerli olmaz, gösteriş ya da dünyevi çıkar için yapılan ibadetin kıymeti yoktur. “Ameller niyetlere göredir...” · “Allah sizin dış görünüşünüze ve mallarınıza bakmaz, ancak kalplerinize ve amellerinize bakar.”</li><li><b>İhlas:</b> Sözlükte samimi bağlılık, temizlik ve saflık. Yalnız Allah'ın rızasını gözetmek, kalbi gösterişten temizleyip içtenlikle yönelmek. “... O hâlde sen de dini Allah'a has kılarak (ihlas ile) kulluk et.” (Zümer suresi 2) En güzel örnek peygamberlerdir: teklif edilen makamı ve parayı reddedip görevlerini yalnız Allah için yaptılar.</li><li><b>Sünnete uygunluk:</b> İbadeti Peygamberimizin öğrettiği ve bizzat uyguladığı şekilde yapmak. “Kim peygambere itaat ederse Allah'a itaat etmiş olur…” (Nisa suresi 80) · “Sözün en güzeli Allah'ın Kitabı'dır. Rehberliğin en güzeli ise Muhammed'in rehberliğidir.”</li></ol><p>Dört ilke birbirini <b>tamamlar</b>: biri eksik olursa ibadet amacına ulaşmaz.</p>"},
            {t:"Sünnetin iki çeşidi", h:"<ul><li><b>Sünnetimüekkede:</b> Peygamberimizin <b>devamlı</b> yaptığı, çok az terk ettiği sünnetler. Örnek: sabah, öğle ve akşam namazlarının sünneti. Yapan dinen övülür, terk eden kınanır.</li><li><b>Sünneti gayrimüekkede:</b> Peygamberimizin <b>bazen yapıp bazen terk ettiği</b> sünnetler. Örnek: ikindi ve yatsı namazlarının ilk sünnetleri. Yapan övgüyü hak eder, terk edene kınama yoktur.</li></ul><p><b>Hatırlatma:</b> Sünnet, Peygamberimizin farz ve vacipler dışında yaptığı ve bize de tavsiye ettiği ibadet ve davranışlardır. Müstehabı ise Peygamberimiz <b>ara sıra</b> yapmıştır.</p>"},
            {t:"Ayet ve hadislerde geçen ibadetlerin hükmü", h:"<ul><li>“Namazı dosdoğru kılın, zekâtı verin...” (Bakara suresi 110) → beş vakit namaz ve zekât: <b>farz</b></li><li>“Kim inanarak ve karşılığını Allah'tan bekleyerek ramazan orucunu tutarsa geçmiş günahları bağışlanır.” → ramazan orucu: <b>farz</b></li><li>“O hâlde Rabbin için namaz kıl ve kurban kes.” (Kevser suresi 2) → kurban kesmek: <b>vacip</b></li><li>“Yarım hurma (sadaka) ile bile olsa cehennemden korunun...” → sadaka vermek: <b>sünnet</b></li><li>“... Aranızda selamı yayın.” → selamlaşmak: <b>sünnet</b></li></ul><p><b>Dikkat:</b> <b>sadaka</b> sünnettir, <b>fıtır sadakası (fitre)</b> ise vaciptir.</p>"},
            {t:"Rakib, Şekur, Hamid: ayet ve hadislerle", h:"<ul><li><b>Rakib:</b> Kur'an'da Allah'ın insanları ve her şeyi gözetlediği bildirilir (Nisa suresi 1, Ahzab suresi 52). Allah aklımızdan geçeni, niyetimizi ve ibadetlerimizdeki samimiyeti de bilir. Bunu bilen mümin yalnızken de davranışına dikkat eder, ibadetlerini aksatmaz.</li><li><b>Şekur:</b> “... Kim bir iyilik işlerse onun sevabını fazlasıyla veririz. Şüphesiz Allah bağışlayan, şükrün karşılığını verendir.” (Şura suresi 23) Peygamberimiz, insanlar geçsin diye yoldaki engeli kaldırmanın ve susamış bir hayvana su vermenin mükâfatlandırılacağını müjdelemiştir.</li><li><b>Hamid:</b> “Hamt (övme ve övülme) âlemlerin Rabbi olan Allah'a mahsustur.” (Fatiha suresi 2) · “Allah'a hamt ile başlanılmayan her önemli iş noksandır.” · Nimet karşısında “Elhamdülillah” demek, o nimetten daha değerlidir.</li></ul><p>Kitaptaki dörtlüklerde de Rakib'in her şeyi takip ettiği, Şekur'un azıcık amele hesapsız sevap verdiği, Hamid'in binlerce kez övülmeye layık olduğu anlatılır.</p>"}],
       tbl:[{h:["Vakti ve şartları belirlenmiş ibadet","Kimler · ne zaman","Kısaca","İnsana kazandırdığı"], r:[
          ["<b>Namaz</b>","Akıllı ve ergenlik çağına gelmiş Müslümanlar · günün belli vakitleri","Kulluğun ifadesi, beden, dil ve kalple Allah'a yönelmek. Bütün ibadetlerin özü.","Düzenli yaşamak. Abdestle temizlik ve günahlardan arınma. Cemaatle birlik."],
          ["<b>Oruç</b>","Akıllı, ergenlik çağına gelmiş ve sağlıklı Müslümanlar · ramazan ayı","İmsaktan iftara kadar ibadet niyetiyle yeme, içme gibi orucu bozan davranışlardan uzak durmak","Açlık ve susuzluğa karşı sabır, nimetlere şükür"],
          ["<b>Fıtır sadakası (fitre)</b>","İmkân sahibi Müslümanlar · ramazan ayı","Allah'a şükür için ihtiyaç sahiplerine verilen sadaka","Paylaşma, zenginle fakir arasında köprü"],
          ["<b>Zekât</b>","Dinen zengin Müslümanlar · yılda bir kez","Malın belli bir miktarını ihtiyaç sahipleriyle paylaşmak","Her şeyin asıl sahibinin Allah olduğunu hatırlamak, dayanışma"],
          ["<b>Hac</b>","Yolculuğa gücü yeten Müslümanlar · yılın belli bir vakti (ömürde bir kez farz)","Kâbe'yi ve çevresindeki kutsal yerleri usulüne uygun ziyaret etmek","Dil, ırk, renk ayrımı olmadan kardeşlik ve birlik"],
          ["<b>Kurban</b>","Dinen zengin Müslümanlar · Kurban Bayramı günleri","Belli özellikteki bir hayvanı ibadet niyetiyle usulüne uygun kesmek. Allah'a teslimiyetin göstergesi.","Sevilen şeylerden fedakârlık, paylaşma"]]},
            {h:["Hüküm","Tanımı","Yapmayan / yapan","Örnekler"], r:[
          ["<b>Farz</b>","Allah'ın yapılmasını kesin olarak emrettiği ibadet","Yapmayan günah işler, inkâr eden dinden çıkar.","Beş vakit namaz, ramazan orucu, yılda bir zekât, ömürde bir hac"],
          ["<b>Vacip</b>","Farz kadar açık ve kesin olmasa da yapılması emredilen ibadet","Yapmayan da inkâr eden de günah işler.","Kurban kesmek, fıtır sadakası, bayram namazı, vitir namazı"],
          ["<b>Sünnet</b>","Peygamberimizin farz ve vacip dışında yaptığı, bize de tavsiye ettiği ibadet ve davranış","Müekkedeyi yapan övülür, terk eden kınanır. Gayrimüekkedeyi yapan övgüyü hak eder, terk edene kınama yoktur.","Teravih namazı, sadaka, selamlaşmak, suyu üç yudumda içmek"],
          ["<b>Müstehap</b>","Yapılması hoş ve güzel karşılanan ama zorunlu tutulmayan, Peygamberimizin ara sıra yaptığı ibadet ve davranış","Zorunlu değildir, yapılması güzel karşılanır.","Nafile namaz ve oruç, sabah namazını ortalık aydınlanınca, akşam namazını geciktirmeden kılmak"]]},
            {h:["İsim","Sözlük anlamı","Allah için anlamı","Bu ismi bilen mümin"], r:[
          ["<b>Rakib</b>","Gözetleyip kontrol eden","Her işi ve yarattığı her varlığı daima koruyup gözeten. Yarattıklarından bir an bile habersiz değildir, aklımızdan geçeni ve niyetimizi bilir.","Yalnızken de davranışına dikkat eder, her işinden sorumlu olduğunu bilir, ibadetlerini aksatmadan, ihlasla ve özenle yapar."],
          ["<b>Şekur</b>","Çokça teşekkür eden","Kullarının salih amellerine bol mükâfat veren. İyiliğin miktarına bakmadan karşılığını fazlasıyla verir, nimetleri artırır, günahları bağışlar.","Allah'ın cömertliği karşısında şükreder, hiçbir iyiliğin boşa gitmeyeceğini bilir, küçük de olsa iyilik yapmayı sürdürür."],
          ["<b>Hamid</b>","Övgüye layık olan, övülen ve öven (hamt: övme)","Bütün varlıkların övdüğü, nimetleri için şükrettiği, övülmeye layık tek varlık. Bütün güzel sıfatların sahibi.","Yalnız Allah'ı över. İbadet, dua, zikir ve şükürle O'na hamdeder, her hâlinde “Elhamdülillah” der."]]},
            {h:["Durum","Kavram / isim"], r:[
          ["Kimse görmese de kurallara uymak, “Rabbim beni görüyor.” demek","Rakib"],
          ["Küçük bir iyiliğin bile karşılıksız kalmayacağını bilmek","Şekur"],
          ["Güzel de olsa zor da olsa her hâlde “Elhamdülillah” demek","Hamid"],
          ["Hangi namazı kılacağını kalbinden belirleyip başlamak","Niyet"],
          ["Yardımını gösteriş için değil, Allah rızası için yapıp kimseye anlatmamak","İhlas"],
          ["Namazı Peygamberimizin öğrettiği şekilde kılmak","Sünnete uygunluk"],
          ["Güzel davranışın ibadet sayılması için önce Allah'a inanmak","İman"],
          ["Allah rızası için ağaç dikmek, susamış bir hayvana su vermek","Salih amel (vakti belirlenmemiş ibadet)"],
          ["Ergenlik çağına girip dinî sorumluluk taşımak","Mükellef"],
          ["Kurban kesmek, fitre vermek, vitir namazı kılmak","Vacip"],
          ["Teravih kılmak, selamlaşmak, sadaka vermek","Sünnet"],
          ["Nafile oruç tutmak","Müstehap"]]},
            {h:["Öğrenme çıktısı (2. yazılı)","S1","S2","S3","S4","S5"], r:[
          ["TDB.1.2.1 İbadetle ilgili öğrendiklerini hayatına yansıtma (2.1)","2","1","1","2","2"],
          ["TDB.1.2.2 İbadetin temel ilkeleri konusunda analitik düşünme (2.2)","1","2","2","2","2"],
          ["TDB.1.2.3 İbadetlerin hükümlerini mukayese etme (2.3)","1","1","1","1","1"],
          ["TDB.1.2.4 Allah'ın güzel isimleri: Rakib, Şekur, Hamid (2.4)","1","1","2","1","2"],
          ["Toplam","5","5","6","6","7"]]}],
       trap:"<b>Farz ile vacibi karıştırmak.</b> Kurban, fitre, bayram ve vitir namazı <b>vaciptir</b>. Beş vakit namaz, ramazan orucu, zekât ve hac <b>farzdır</b>. İkinci tuzak: <b>sadaka</b> ile <b>fıtır sadakasını</b> aynı sanmak. Sadaka sünnet, fıtır sadakası (fitre) vaciptir. Üçüncüsü: teravihi farz, nafile namazı vacip sanmak. Teravih <b>sünnet</b>, nafile namaz ve oruç <b>müstehaptır</b>. Dördüncüsü: <b>niyet</b> ile <b>ihlası</b> karıştırmak. Niyet hangi ibadeti yapacağına karar verip onu Allah için yapmak, ihlas ise yalnız Allah'ın rızasını gözetip gösterişten uzak, içtenlikle yapmaktır. Beşincisi: <b>Şekur</b> ile <b>Hamid</b>'i karıştırmak. Şekur iyiliğe bol karşılık veren, Hamid her türlü övgüye layık olandır. Altıncısı: yalnız namaz, oruç gibi vakti belli ibadetleri ibadet sanmak. Allah rızası için yapılan güler yüz, temizlik, dürüstlük de ibadettir.",
       voc:[["ibadet","Allah'ın emrettiği ve insanın O'na karşı yapmakla yükümlü olduğu davranışlar; Allah'ı yüceltmek, O'na itaat ve kulluk etmek"],["kulluk","Allah'a itaat etmek: “Yap!” dediğini yapmak, “Yapma!” dediğinden uzak durmak"],["rıza","Allah'ın hoşnutluğu; ibadetin esas amacı O'nun rızasını kazanmaktır"],
            ["hamt","Allah'ı övmek, yüceltmek, O'na şükretmek"],["salih amel","Allah rızası için yapıldığında ibadet sayılan iyi, doğru ve faydalı iş ve davranışlar (salih: iyi, doğru, faydalı · amel: iş)"],["tevhit","Allah'ın varlığına ve birliğine inanmak; İslam'ın temel esası"],
            ["rızık","Allah'ın her varlığa verdiği; yenilen, içilen, giyilen, maddi ve manevi yararlanılan her şey"],["oruç","imsaktan iftara kadar ibadet niyetiyle yeme, içme gibi orucu bozan davranışlardan uzak durmak"],["fıtır sadakası (fitre)","ramazanda imkân sahibi Müslümanın Allah'a şükür için ihtiyaç sahiplerine verdiği sadaka"],
            ["zekât","dinen zengin Müslümanın malının belli bir miktarını yılda bir kez ihtiyaç sahipleriyle paylaşması"],["hac","yılın belli bir vaktinde Kâbe'yi ve çevresindeki kutsal yerleri usulüne uygun ziyaret etmek"],["kurban","dinen zengin Müslümanın Kurban Bayramı günlerinde belli özellikteki hayvanı ibadet niyetiyle kesmesi"],
            ["niyet","bir işin yapılış amacı; hangi ibadeti yapacağına karar verip onu Allah için yapmak"],["ihlas","sözlükte samimi bağlılık, temizlik, saflık; yalnız Allah'ın rızasını gözetmek, gösterişten uzak durmak"],["sünnete uygunluk","ibadetleri Peygamberimizin öğrettiği ve uyguladığı şekilde yapmak"],
            ["mükellef","akli dengesi yerinde ve ergenlik çağına ulaşmış, dinî sorumluluk taşıyan kişi"],["farz","Allah'ın yapılmasını kesin olarak emrettiği ibadet"],["vacip","farz kadar açık ve kesin olmasa da yapılması emredilen ibadet"],
            ["sünnet (hüküm)","Peygamberimizin farz ve vacip dışında yaptığı, bize de tavsiye ettiği ibadet ve davranış"],["sünnetimüekkede","Peygamberimizin devamlı yapıp nadiren terk ettiği sünnet (sabah, öğle, akşam namazının sünneti)"],["sünneti gayrimüekkede","Peygamberimizin bazen yapıp bazen terk ettiği sünnet (ikindi ve yatsının ilk sünneti)"],
            ["müstehap","yapılması hoş ve güzel karşılanan ama zorunlu tutulmayan, Peygamberimizin ara sıra yaptığı ibadet"],["nafile","zorunlu olmadan, fazladan yapılan namaz ve oruç; müstehap kapsamındadır"],["Rakib","sözlükte gözetleyip kontrol eden; her işi ve her varlığı daima koruyup gözeten"],
            ["Şekur","çokça teşekkür eden; kullarının iyiliklerine bol mükâfat veren"],["Hamid","övgüye layık olan, övülen ve öven"],["Elhamdülillah","“Her türlü övgü Allah'a mahsustur.”"]],
       q:["İbadet nedir? Tanımını yazınız ve ibadetin içerdiği anlamlardan üçünü belirtiniz.",
          "Can bir gün içinde öğle namazını kıldı, parkta yere atılmış çöpleri topladı, ödevinde zorlanan kardeşine yardım etti ve yatmadan önce dua etti. Bunların hepsini Allah'ın rızasını kazanmak için yaptı. Can'ın davranışlarını “vakti ve şartları belirlenmiş” ve “belirlenmemiş” ibadetler olarak sınıflandırınız.",
          "Vakti ve şartları belirlenmiş ibadetlerden dördünü yazınız. Bunlardan birinin tanımını yapınız.",
          "Salih amel ne demektir? Bir iyiliğin salih amel sayılması için ne gerekir? İki örnek veriniz.",
          "İbadetin amacı nedir? Şükür, hamt, itaat ve kulluk kavramlarından üçünü kullanarak açıklayınız.",
          "İbadetler insanın kişisel gelişimine nasıl katkı sağlar? Namaz, oruç ve kurban için birer örnekle açıklayınız.",
          "Cemaatle kılınan namaz, hac ve zekât ibadetlerinin toplum hayatına katkılarını açıklayınız.",
          "İbadetin temel ilkeleri (kabul şartları) nelerdir? Her birini birer cümleyle açıklayınız.",
          "Emre sahurdan sonra hangi orucu tutacağını kalbinden belirleyerek ramazan orucuna niyet etti. Gün boyu oruçlu olduğunu insanlara anlatıp övgü beklemedi. Akşam namazını da Peygamberimizin öğrettiği şekilde kıldı. Emre'nin davranışlarını ibadetin temel ilkeleriyle eşleştiriniz.",
          "Bir kişi, insanlar onu cömert biri sansın diye büyük bir bağış yapıyor ve bunu herkese anlatıyor. Bu davranışı ibadetin temel ilkeleri açısından değerlendiriniz.",
          "İbadetin temel ilkeleri birbirini nasıl tamamlar? Biri eksik olursa ne olur? “… Allah katında amellerin en sevimlisi, az da olsa devamlı olanıdır.” hadisini de kullanarak açıklayınız.",
          "Mükellef kime denir? Mükellef olan bir kişinin sorumlulukları nelerdir?",
          "Farz ile vacibi benzer ve farklı yönleriyle karşılaştırınız. Her birine iki örnek veriniz.",
          "Sünnet ile müstehabı karşılaştırınız. Sünnetimüekkede ve sünneti gayrimüekkedeye birer örnek veriniz.",
          "Şu ibadetleri hükümlerine göre sınıflandırınız: ramazan orucu, teravih namazı, kurban kesmek, nafile oruç, vitir namazı, selamlaşmak, hacca gitmek, fıtır sadakası.",
          "Teneffüste sınıfta tek başına kalan Mert, arkadaşının sırasında unutulmuş parayı gördü. “Kimse görmüyor ama Rabbim görüyor.” diyerek parayı öğretmenine teslim etti. Mert'in davranışı Allah'ın hangi ismini bildiğini gösterir? Bu ismin anlamını yazınız.",
          "“... Kim bir iyilik işlerse onun sevabını fazlasıyla veririz. Şüphesiz Allah bağışlayan, şükrün karşılığını verendir.” (Şura suresi 23) Bu ayet Allah'ın hangi güzel ismiyle ilgilidir? Bu ismi bilen bir Müslüman nasıl davranır?",
          "Hamid isminin anlamını yazınız. “Elhamdülillah” sözü ile bu isim arasındaki ilişkiyi açıklayınız.",
          "Rakib, Şekur ve Hamid isimlerini birbirinden ayırt ediniz: her biri için bir günlük hayat davranışı yazınız."],
       a:["<b>İbadet</b>, Allah'ın emrettiği ve insanların O'na karşı yapmakla <b>yükümlü</b> olduğu davranışlardır. Anlamları: Allah'ı <b>yüceltmek ve övmek</b>, O'na <b>boyun eğmek</b>, <b>itaat</b> etmek, saygı göstermek, <b>kulluk</b> etmek. Allah'ın razı olacağı her davranış, duygu ve düşünce ibadettir.",
          "<b>Vakti ve şartları belirlenmiş:</b> öğle namazını kılmak. <b>Vakti ve şartları belirlenmemiş:</b> çöpleri toplamak (çevreyi korumak, temizlik), kardeşine yardım etmek, dua etmek. Allah'ın rızası için yapıldıkları için hepsi <b>ibadet</b> (salih amel) sayılır.",
          "Namaz, oruç, fıtır sadakası (fitre), zekât, hac, kurban (dördü yeterli). Örnek tanım: <b>Zekât</b>, dinen zengin olan Müslümanın malının belli bir miktarını <b>yılda bir kez</b> ihtiyaç sahipleriyle paylaşmasıdır. Ya da <b>oruç</b>, imsaktan iftara kadar ibadet niyetiyle yeme, içme gibi orucu bozan davranışlardan uzak durmaktır.",
          "<b>Salih amel</b>, Allah rızası için yapıldığında ibadet sayılan <b>iyi, doğru ve faydalı</b> iş ve davranışlardır (salih: iyi, doğru, faydalı · amel: iş). Salih amel sayılması için yapanın <b>mümin</b> olması (Allah'a iman etmesi) ve işi Allah'ın rızasını gözeterek yapması gerekir. Örnekler: namaz kılmak, selamlaşmak, ağaç dikmek, hayvanlara merhamet göstermek, ihtiyaç sahibine yardım etmek.",
          "İbadetin esas amacı <b>Allah'ın rızasını kazanmaktır</b>. İbadet eden kişi sayısız nimet veren Rabbine <b>şükreder</b> (teşekkür eder), O'nu över ve yüceltir (<b>hamt</b>), emirlerini yerine getirip yasaklarından uzak durarak <b>itaat</b> eder ve <b>kulluk</b> görevini yapar. Böylece Allah'a bağlılığını gösterir.",
          "Her ibadet insanın farklı bir yönünü eğitir, ahlaken gelişmesini ve manevi olarak olgunlaşmasını sağlar. <b>Namaz</b> günde beş vakit kılındığı için <b>düzenli yaşamaya</b> alıştırır. <b>Oruç</b> açlık ve susuzluğa karşı <b>sabrı</b> öğretir. <b>Kurban</b> sevilen şeylerden <b>fedakârlık</b> etmeyi öğretir. (Abdest temizlik alışkanlığı kazandırır, zekât ve sadaka paylaşmaya teşvik eder.)",
          "<b>Cemaatle namaz:</b> Müslümanlar camide bir araya gelir, tanışır, kaynaşır, sevinç ve sıkıntılarını paylaşır, <b>birlik ve beraberlik</b> güçlenir. <b>Hac:</b> dünyanın dört bir yanından gelen Müslümanlar buluşur, dil, ırk ve renk ayrımı ortadan kalkar. <b>Zekât</b> (fitre ve kurban da): zenginle fakir arasında <b>köprü</b> olur, dostluk ve kardeşliği geliştirir, ekonomik ve sosyal adaletsizliği önler, <b>dayanışmayı</b> güçlendirir.",
          "<b>İman:</b> Allah'ın varlığına, birliğine ve iman esaslarına kesin olarak inanmaktır, iyi davranışların ibadet sayılmasının ilk şartıdır. <b>Niyet:</b> hangi ibadeti yapacağına karar verip onu Allah için yapmaktır, kalple yapılır, dille de söylenir. <b>İhlas:</b> yalnız Allah'ın rızasını gözetmek, ibadeti gösterişten uzak ve içtenlikle yapmaktır. <b>Sünnete uygunluk:</b> ibadeti Peygamberimizin öğrettiği ve uyguladığı şekilde yapmaktır.",
          "<b>Niyet:</b> hangi orucu tutacağını kalbinden belirleyip niyet etmesi. <b>İhlas:</b> oruçlu olduğunu anlatıp övgü beklememesi, yalnız Allah'ın rızasını gözetmesi. <b>Sünnete uygunluk:</b> namazını Peygamberimizin öğrettiği şekilde kılması. <b>İman:</b> bütün bu davranışların temelinde Allah'a inanması vardır, iman olmadan bunlar ibadet değeri kazanmaz.",
          "Bu kişi bağışı <b>Allah rızası için değil, gösteriş için</b> yapmıştır. Gösteriş ya da dünyevi çıkar için yapılan ibadetin <b>kıymeti yoktur</b>. Davranış <b>niyet</b> ve <b>ihlas</b> ilkelerine uymaz: ibadette niyet yalnız Allah'ın rızasını kazanmak olmalı, ibadet içtenlikle ve gösterişten uzak yapılmalıdır. Peygamberimiz “Allah sizin dış görünüşünüze ve mallarınıza bakmaz, ancak kalplerinize ve amellerinize bakar.” buyurmuştur.",
          "İbadetin Allah katında geçerli olması için <b>iman</b> ile, Allah'ın rızası gözetilerek (<b>niyet</b>), <b>ihlasla</b> ve <b>sünnete uygun</b> yapılması gerekir. Bu ilkeler birbirini tamamlar, biri <b>eksik olursa ibadet amacına ulaşmaz</b>. Hadis, ibadetin az da olsa <b>düzenli ve devamlı</b> yapılmasının değerini gösterir. İbadetini sürdüren kişinin <b>disiplin ve sorumluluk</b> duygusu gelişir, Rabbiyle bağı güçlenir.",
          "<b>Mükellef</b>, sorumluluk taşıyan kişidir: <b>akli dengesi yerinde</b> ve <b>ergenlik çağına ulaşmış</b> kimse. Bedensel ve zihinsel olgunluğa erişmiştir. Allah'ın <b>emirlerinden, yasaklarından ve ibadetlerden</b> sorumludur. Dinî sorumluluklarının başında ibadetler gelir.",
          "<b>Benzerlik:</b> İkisinin de yapılması dinimizce emredilmiştir, yerine getirmeyen <b>günah</b> işlemiş olur. <b>Fark:</b> Farz Allah'ın <b>kesin</b> emridir, inkâr eden dinden çıkar. Vacip farz kadar açık ve kesin değildir, inkâr eden günah işlemiş olur. <b>Farz:</b> beş vakit namaz, ramazan orucu, zekât, hac. <b>Vacip:</b> kurban kesmek, fıtır sadakası vermek, bayram ve vitir namazı.",
          "<b>Benzerlik:</b> İkisi de farz ve vacip dışındadır, Peygamberimizin yaptığı ve <b>güzel görülen</b> ibadet ve davranışlardır. <b>Fark:</b> Sünneti Peygamberimiz yapmış ve bize de yapmamızı <b>tavsiye</b> etmiştir. Müstehabı ise <b>ara sıra</b> yapmıştır, yapılması hoş karşılanır ama <b>zorunlu tutulmaz</b>. <b>Sünnetimüekkede</b> (devamlı yaptığı): sabah, öğle ve akşam namazlarının sünneti. <b>Sünneti gayrimüekkede</b> (bazen yapıp bazen terk ettiği): ikindi ve yatsı namazlarının ilk sünnetleri.",
          "<b>Farz:</b> ramazan orucu, hacca gitmek. <b>Vacip:</b> kurban kesmek, vitir namazı, fıtır sadakası. <b>Sünnet:</b> teravih namazı, selamlaşmak. <b>Müstehap:</b> nafile oruç.",
          "<b>Rakib</b> ismini. Rakib sözlükte <b>gözetleyip kontrol eden</b> demektir. Allah her işi ve yarattığı her varlığı <b>daima koruyup gözetir</b>, bir an bile habersiz değildir, kalbimizden geçeni de bilir. Bu ismi bilen mümin yalnızken de davranışlarına dikkat eder, yaptığı her işten sorumlu olduğunu bilir.",
          "<b>Şekur</b> ismiyle ilgilidir. Şekur çokça teşekkür eden demektir. Allah, iyiliğin <b>miktarına ve büyüklüğüne bakmadan</b> karşılığını <b>fazlasıyla</b> verir. Bu ismi bilen Müslüman Allah'ın cömertliği karşısında O'na <b>şükreder</b>, hiçbir iyiliğinin boşa gitmeyeceğini bilerek <b>küçük de olsa iyilik yapmayı sürdürür</b>.",
          "Hamt sözlükte <b>övme</b>, <b>Hamid</b> ise <b>övgüye layık olan, övülen ve öven</b> demektir. Allah, bütün varlıkların övdüğü ve verdiği nimetler için şükrettiği, <b>övülmeye layık tek varlıktır</b>. “Elhamdülillah” <b>“Her türlü övgü Allah'a mahsustur.”</b> demektir. Hamid ismini bilen mümin, hoşuna giden de gitmeyen de her hâlinde “Elhamdülillah” diyerek Allah'ı över.",
          "<b>Rakib:</b> yalnızken de kurallara uymak, Allah'ın her an gördüğünü bilerek dürüst davranmak. <b>Şekur:</b> küçük de olsa bir iyiliği (yoldaki taşı kaldırmak, bir hayvana su vermek) Allah'ın karşılıksız bırakmayacağını bilerek yapmak. <b>Hamid:</b> nimetler karşısında ve her hâlde “Elhamdülillah” diyerek Allah'ı övmek, işlere hamt ile başlamak."]},

      {n:"İslam Ölçülü Olmamızı İster", w:"Şubat–Mart–Nisan",
       lead:"Hayatın farklı alanlarında ölçülü olmayı işler. Kitaptaki bölümler: <b>3.1</b> Mahremiyette Ölçümüz · <b>3.2</b> Kardeşlikte Ölçümüz · <b>3.3</b> Tasarrufta Ölçümüz · <b>3.4</b> Allah'ın Güzel İsimleri: Hafiz, Vedud, Kerim. Konu anlatımı ve sorular ünite başlarken eklenecek."},

      {n:"İslam'la Değerlenen Hayatımız", w:"Nisan–Mayıs–Haziran",
       lead:"Müslümanın irade, ilim ve hayâ ile değer kazanan hayatını işler. Kitaptaki bölümler: <b>4.1</b> Müslüman İrade Sahibidir · <b>4.2</b> Müslüman İlim ile Yücelir · <b>4.3</b> Müslüman Hayâ ile Güzelleşir · <b>4.4</b> Allah'ın Güzel İsimleri: Muktedir, Hakim, Cemil. Konu anlatımı ve sorular ünite başlarken eklenecek."}
     ]}
  );

  /* Yıllık takvime bu dersin satırları. Kitap sayfa sayısına ve sınav tablosuna
     göre: 1. ünite 1. yazılıya (Kasım ortası), 2. ünite yarıyıl tatiline kadar;
     2. dönemde 3. ve 4. ünite. */
  (function(){
    var T = {
      eylul:"Dinimiz İslam", ekim:"Dinimiz İslam", kasim:"Dinimiz İslam / Hayatımız İbadet",
      aralik:"Hayatımız İbadet", ocak:"Hayatımız İbadet",
      subat:"İslam Ölçülü Olmamızı İster", mart:"İslam Ölçülü Olmamızı İster",
      nisan:"İslam Ölçülü Olmamızı İster / İslam'la Değerlenen Hayatımız",
      mayis:"İslam'la Değerlenen Hayatımız", haziran:"İslam'la Değerlenen Hayatımız"
    };
    CAL6.forEach(function(r){ if(r.items && T[r.key]) r.items.push(["tdb", T[r.key]]); });
  })();

  /* ---------- ana test: ünite başına 10 ---------- */
  Q6.tdb = [
    {u:"ÜNİTE 1 · Dinimiz İslam", q:"“Andolsun, Allah'ın Resulü'nde sizin için ... güzel bir örnek vardır.” (Ahzab suresi 21)\n\nBu ayete göre Müslümanlar Peygamberimizin hayatına nasıl bakmalıdır?", o:["Kendi davranışlarına yön veren bir örnek olarak","Yalnızca geçmişte kalmış bir hikâye olarak","Sadece sahabeyi ilgilendiren bir konu olarak","Sadece ibadetlerde uyulacak bir rehber olarak"], a:0,
     w:"Ayet Peygamberimizin Müslümanlar için güzel bir örnek olduğunu bildirir. O yalnız ibadetiyle değil ahlakıyla, kişiliğiyle ve aile hayatıyla da örnektir. Bu örnek hayata sünnet denir."},
    {u:"ÜNİTE 1 · Dinimiz İslam", q:"Kur'an'da namaz kılmanın farz olduğu bildirilmiştir. Namazın vakitleri, rekât sayıları ve nasıl kılınacağı ise ayrıntılı olarak nereden öğrenilir?", o:["Peygamberimizin sünnetinden","Tevrat ve İncil'den","Kur'an'daki peygamber kıssalarından","Hac ibadetinin kurallarından"], a:0,
     w:"Kur'an bazı hükümleri genel olarak bildirir, ayrıntıyı sünnet açıklar. Peygamberimiz “Beni nasıl namaz kılıyor gördüyseniz siz de namazı öyle kılınız.” buyurmuştur."},
    {u:"ÜNİTE 1 · Dinimiz İslam", q:"“Sünnet” kavramının dinî terim anlamı aşağıdakilerden hangisidir?", o:["Hz. Peygamber'in sözleri, davranışları ve sahabenin uygulamalarını onaylaması","Kur'an ayetlerinin sahabe tarafından ezberlenip yazılarak korunması","Müslümanların her gün belirli vakitlerde kılması gereken farz namazlar","Allah'ın insanlara Hz. Muhammed aracılığıyla gönderdiği son ilahi kitap"], a:0,
     w:"Sünnet sözlükte “yol, âdet, gidişat” demektir. Terim olarak Peygamberimizin sözü, davranışı ve onayıdır. Son ilahi kitap ise Kur'an'dır; sünnet bir kitap değildir."},
    {u:"ÜNİTE 1 · Dinimiz İslam", q:"“Şüphesiz o zikri (Kur'an'ı) biz indirdik biz! Onun koruyucusu da elbette biziz.” (Hicr suresi 9)\n\nBu ayet Kur'an'ın hangi özelliğini vurgular?", o:["Değişmeden günümüze ulaşmasını","Peygamberimizin en büyük mucizesi olmasını","Okunmasının ibadet sayılmasını","Ayetleri üzerinde düşünülmesi gerektiğini"], a:0,
     w:"Ayet Kur'an'ın korunacağını bildirir. Önceki ilahi kitaplar değiştirildi; Kur'an ise okunarak ve ezberlenerek hiç değişmeden günümüze ulaştı."},
    {u:"ÜNİTE 1 · Dinimiz İslam", q:"İnanmanın insan hayatına katkılarıyla ilgili aşağıdakilerden hangisi SÖYLENEMEZ?", o:["İnsana iç huzuru ve güven duygusu verir.","Zorluklar karşısında umudunu korumasına yardım eder.","İnsana bu dünyada yalnız olmadığını hissettirir.","İnsanı yapması gereken sorumluluklardan kurtarır."], a:3,
     w:"İnanmak sorumluluğu kaldırmaz; mümin üzerine düşeni yapar, sonra Allah'a güvenir. Huzur, güven, manevi dayanıklılık ve yalnız olmadığını hissetmek ise inanmanın kazandırdıklarıdır."},
    {u:"ÜNİTE 1 · Dinimiz İslam", q:"Her insanın doğuştan getirdiği, yüce bir yaratıcıya inanma eğilimine ne ad verilir?", o:["Fıtrat","Tevekkül","Salih amel","Hidayet"], a:0,
     w:"Fıtrat, yaratılıştan gelen inanma ihtiyacı ve iyiliğe yönelimdir. Peygamberimiz “Her doğan çocuk fıtrat üzere doğar...” buyurmuştur."},
    {u:"ÜNİTE 1 · Dinimiz İslam", q:"Kalben inanmadığı hâlde Müslümanların arasında inandığını söyleyen kişiye ne denir?", o:["Kâfir","Münafık","Mümin","Hanif"], a:1,
     w:"Münafık ikiyüzlüdür: dili “inanıyorum” der, kalbi inanmaz. Kâfir ise inanmadığını açıkça söyler; mümin hem kalbiyle inanır hem diliyle söyler."},
    {u:"ÜNİTE 1 · Dinimiz İslam", q:"Aşağıdakilerden hangisi İslam'ın inanç esaslarından biri DEĞİLDİR?", o:["Meleklere iman","Ahiret gününe iman","Zekât vermek","Kader ve kazaya iman"], a:2,
     w:"Zekât vermek İslam'ın şartlarındandır, inanç esası değildir. Meleklere, ahiret gününe, kader ve kazaya iman ise inanç esaslarıdır."},
    {u:"ÜNİTE 1 · Dinimiz İslam", q:"Kitaba göre insana sabretmeyi, iradesine hâkim olmayı ve ihtiyaç sahiplerinin hâlinden anlamayı öğreten ibadet hangisidir?", o:["Namaz","Oruç","Zekât","Hac"], a:1,
     w:"Oruç tutan kişi yemekten ve içmekten uzak durarak sabrı ve iradesine hâkim olmayı öğrenir, ihtiyaç sahiplerinin hâlini anlar. Namaz disiplin, zekât paylaşma, hac kardeşlik kazandırır."},
    {u:"ÜNİTE 1 · Dinimiz İslam", q:"“Kullarını doğru yola ileten, onlara rehberlik eden” anlamına gelen güzel isim hangisidir?", o:["Hâdi","Selam","Vekîl","Hamid"], a:0,
     w:"Hâdi doğru yolu gösteren demektir. Namazda okunan “Bizi dosdoğru yola ilet.” ayetiyle bu isme yöneliriz."},
    {u:"ÜNİTE 2 · Hayatımız İbadet", q:"“Allah'ı övmek, yüceltmek ve O'na şükretmek” anlamına gelen kavram hangisidir?", o:["Hamt","Niyet","Tevhit","Rızık"], a:0,
     w:"Hamt, Allah'ı övmek, yüceltmek ve O'na şükretmek demektir. Rabbini seven kişi ibadet ederek nimetlerin kaynağı olan Allah'a hamdetmiş olur."},
    {u:"ÜNİTE 2 · Hayatımız İbadet", q:"Ayşe okul bahçesine fidan dikiyor, sokak hayvanlarına su koyuyor, arkadaşlarına güler yüzle selam veriyor. Bunları Allah'ın rızasını kazanmak için yapıyor.\n\nAyşe'nin bu davranışları hangi kavramla ifade edilir?", o:["Mükellef","Salih amel","Fıtır sadakası","Tevhit"], a:1,
     w:"Allah rızası için yapılan iyi, doğru ve faydalı işlere salih amel denir. Ağaç dikmek, hayvanlara merhamet göstermek ve selamlaşmak da salih amellerdendir."},
    {u:"ÜNİTE 2 · Hayatımız İbadet", q:"Aşağıdakilerden hangisi vakti ve şartları belirlenmiş ibadetlerden biri DEĞİLDİR?", o:["Kurban kesmek","Fıtır sadakası vermek","Dua etmek","Zekât vermek"], a:2,
     w:"Dua etmek belli bir vakte, şekle ve şarta bağlı değildir, insan her an dua edebilir. Kurban, fitre ve zekâtın ise vakti ve şartları dinimizce belirlenmiştir."},
    {u:"ÜNİTE 2 · Hayatımız İbadet", q:"Öğle vakti camiye giren Ahmet, kılacağı namazın öğle namazının farzı olduğunu kalbinden geçirerek namaza başladı.\n\nAhmet'in bu davranışı ibadetin hangi ilkesine örnektir?", o:["İhlas","İman","Sünnete uygunluk","Niyet"], a:3,
     w:"Niyet, hangi ibadeti yapacağına karar verip onu Allah için yapmaktır. Kalple yapılır, dille de söylenir. Niyet olmadan yapılan ibadet geçerli olmaz."},
    {u:"ÜNİTE 2 · Hayatımız İbadet", q:"Sözlükte “samimi bağlılık, temizlik ve saflık” anlamına gelen kavram hangisidir?", o:["Niyet","İhlas","Hamt","Tevhit"], a:1,
     w:"İhlas sözlükte samimi bağlılık, temizlik ve saflık demektir. İbadette yalnız Allah'ın hoşnutluğunu istemek, kalbi gösterişten temizlemektir."},
    {u:"ÜNİTE 2 · Hayatımız İbadet", q:"“Kim peygambere itaat ederse Allah'a itaat etmiş olur...” (Nisa suresi 80)\n\nBu ayet ibadetin temel ilkelerinden en çok hangisiyle ilgilidir?", o:["Sünnete uygunluk","Niyet","İhlas","Vakte uygunluk"], a:0,
     w:"Ayet, Peygamberimize uymanın Allah'a itaat olduğunu bildirir. İbadetleri Peygamberimizin öğrettiği ve bizzat uyguladığı şekilde yapmak sünnete uygunluk ilkesidir."},
    {u:"ÜNİTE 2 · Hayatımız İbadet", q:"İslam'a göre akli dengesi yerinde olan, ergenlik çağına ulaşmış ve Allah'ın emir ve yasaklarından sorumlu tutulan kişiye ne denir?", o:["Mümin","Münafık","Mükellef","Sahabi"], a:2,
     w:"Mükellef, sorumluluk taşıyan kişi demektir. Akli dengesi yerinde ve ergenlik çağına ulaşmış kişi bedensel ve zihinsel olgunluğa eriştiği için dinî sorumluluklarını yerine getirmelidir."},
    {u:"ÜNİTE 2 · Hayatımız İbadet", q:"Kurban kesmek, fıtır sadakası vermek, bayram ve vitir namazı kılmak hangi hükümdeki ibadetlerdendir?", o:["Farz","Sünnet","Müstehap","Vacip"], a:3,
     w:"Kitapta kurban kesmek, fıtır sadakası vermek, bayram ve vitir namazı kılmak vacip ibadetler arasında sayılır. Vacip, farz kadar açık ve kesin olmasa da yapılması emredilen ibadettir."},
    {u:"ÜNİTE 2 · Hayatımız İbadet", q:"Sözlükte “gözetleyip kontrol eden” anlamına gelen güzel isim hangisidir?", o:["Rakib","Şekur","Hamid","Selam"], a:0,
     w:"Rakib sözlükte gözetleyip kontrol eden demektir. Allah her işi ve yarattığı her varlığı daima koruyup gözetir, O'ndan hiçbir şey gizli kalmaz."},
    {u:"ÜNİTE 2 · Hayatımız İbadet", q:"“... Kim bir iyilik işlerse onun sevabını fazlasıyla veririz. Şüphesiz Allah bağışlayan, şükrün karşılığını verendir.” (Şura suresi 23)\n\nBu ayet Allah'ın hangi güzel ismiyle en çok ilgilidir?", o:["Rakib","Şekur","Hamid","Hâdi"], a:1,
     w:"Ayet, iyiliğin karşılığının fazlasıyla verileceğini bildirir. Bu, kullarının iyiliklerine bol mükâfat veren anlamındaki Şekur ismiyle ilgilidir."}
  ];

  /* ---------- havuz: yalnız Yanlışlarım'da çıkar, ünite başına 5 ---------- */
  H6.tdb = [
    {u:"ÜNİTE 1 · Dinimiz İslam", q:"Kur'an-ı Kerim'in Peygamberimizin en büyük mucizesi sayılmasının sebebi aşağıdakilerden hangisidir?", o:["İnsanların ve cinlerin onun bir benzerini getirememesi","Mekke'de ve Medine'de indirilmiş olması","Ramazan ayında indirilmeye başlanmış olması","Sahabe tarafından ezberlenmiş olması"], a:0,
     w:"İsra suresi 88. ayete göre insanlar ve cinler toplanıp birbirine destek olsa da Kur'an'ın benzerini getiremez; çünkü insanların ortaya koyamayacağı bir üslubu ve anlam bütünlüğü vardır."},
    {u:"ÜNİTE 1 · Dinimiz İslam", q:"Peygamberimiz, Kur'an'da geçen “orta namaz” ifadesinin hangi namaz olduğunu açıklamıştır. Orta namaz hangisidir?", o:["Sabah namazı","Öğle namazı","İkindi namazı","Yatsı namazı"], a:2,
     w:"Peygamberimiz “Orta namaz, ikindi namazıdır.” buyurmuştur. Bu, sünnetin Kur'an'daki ifadeleri açıkladığına bir örnektir."},
    {u:"ÜNİTE 1 · Dinimiz İslam", q:"Aşağıdakilerden hangisi İslam'ın beş şartından biri DEĞİLDİR?", o:["Kelimeişehadet getirmek","Hacca gitmek","Oruç tutmak","Kitaplara iman etmek"], a:3,
     w:"Kitaplara iman bir inanç esasıdır, İslam'ın şartlarından değildir. İslam'ın şartları: kelimeişehadet getirmek, namaz kılmak, oruç tutmak, zekât vermek, hacca gitmek."},
    {u:"ÜNİTE 1 · Dinimiz İslam", q:"“Müslüman, dilinden ve elinden insanların selamette olduğu kişidir.” hadisine göre bir Müslüman nasıl davranır?", o:["Sözüyle ve davranışıyla kimseye zarar vermez.","Yalnızca kendi ibadetleriyle ilgilenir.","İnsanlardan uzak, yalnız yaşar.","Sadece tanıdığı kişilere iyi davranır."], a:0,
     w:"“Dilinden ve elinden selamette olmak”, o kişinin sözünden de davranışından da kimsenin zarar görmemesi demektir."},
    {u:"ÜNİTE 1 · Dinimiz İslam", q:"Elinden gelen çabayı gösterdikten sonra sonucu Allah'a bırakıp O'na güvenmeye ne ad verilir?", o:["Tasdik","Tevekkül","Fıtrat","Hidayet"], a:1,
     w:"Tevekkül önce çalışmak, sonra Allah'a güvenmektir; Vekîl ismiyle ilgilidir. Tasdik doğrulamak, fıtrat yaratılıştan gelen inanma ihtiyacı, hidayet doğru yola iletmedir."},
    {u:"ÜNİTE 2 · Hayatımız İbadet", q:"Kitaba göre bütün ibadetlerin özü kabul edilen ibadet hangisidir?", o:["Oruç","Zekât","Namaz","Hac"], a:2,
     w:"Namaz kılan kişi bedeni, dili ve kalbiyle Allah'a yönelir, O'nunla bağ kurar. Bu yüzden namaz bütün ibadetlerin özü sayılır."},
    {u:"ÜNİTE 2 · Hayatımız İbadet", q:"Kitaba göre güzel bir davranışın salih amel sayılmasının öncelikli şartı hangisidir?", o:["Herkesin gözü önünde yapılması","Yapan kişinin mümin olması","Mutlaka camide yapılması","Maddi bir kazanç sağlaması"], a:1,
     w:"Bir iyiliğin salih amel sayılması için onu yapanın Allah'a iman etmiş olması gerekir. İslam'ın temel esası tevhit inancıdır."},
    {u:"ÜNİTE 2 · Hayatımız İbadet", q:"Yapılması hoş ve güzel karşılanan ama zorunlu tutulmayan, Peygamberimizin ara sıra yaptığı ibadet ve davranışlar hangi hükümdedir?", o:["Vacip","Farz","Sünnetimüekkede","Müstehap"], a:3,
     w:"Bunlar müstehaptır. Nafile namazlar ve oruçlar, sabah namazını ortalık aydınlanınca, akşam namazını da geciktirmeden kılmak müstehaba örnektir."},
    {u:"ÜNİTE 2 · Hayatımız İbadet", q:"“Övgüye layık olan, övülen ve öven” anlamına gelen güzel isim hangisidir?", o:["Hamid","Şekur","Rakib","Selam"], a:0,
     w:"Hamid, övgüye layık olan, övülen ve öven demektir. “Hamt (övme ve övülme) âlemlerin Rabbi olan Allah'a mahsustur.” (Fatiha suresi 2)"},
    {u:"ÜNİTE 2 · Hayatımız İbadet", q:"Kitaba göre kurban ibadeti insana en çok neyi öğretir?", o:["Açlık ve susuzluğa karşı sabretmeyi","Düzenli ve planlı yaşamayı","Sevdiği şeylerden fedakârlık etmeyi","Temizliği alışkanlık hâline getirmeyi"], a:2,
     w:"Kurban Allah'a teslimiyetin göstergesidir ve insana sevdiği şeylerden fedakârlık etmeyi öğretir."}
  ];

  /* ---------- ek çalışma seti ----------
     "EK · 1. Yazılı Hazırlık" (26): sınav tablosundaki dört bölüm sırayla —
     1.1 (6), 1.2 (7), 1.3 (8), 1.4 (5). Sınavda şık olmayacak; buradaki sorular
     kavramları ayırt etmek ve öğretmenin soru tipini (durum → “bu neyi gösterir?”)
     tanımak için. */
  EKC6.tdb = [
    {u:"EK · 1. Yazılı Hazırlık", q:"Kadir Bey zekât vermek istiyor ama hangi mallardan ne kadar vereceğini bilmiyor. Kur'an'da zekâtın farz olduğu bildirilmiş, ayrıntısı verilmemiştir.\n\nKadir Bey bu ayrıntıyı öğrenmek için en doğru olarak neye başvurmalıdır?", o:["Peygamberimizin uygulamalarına","Komşularının ne kadar verdiğine","Kendi gelirine göre yaptığı tahmine","Önceki ilahi kitaplara"], a:0,
     w:"Hangi mallardan ne kadar zekât verileceği Peygamberimizin uygulamalarıyla ortaya konmuştur. Öğretmenin namaz sorusu da aynı mantıktadır."},
    {u:"EK · 1. Yazılı Hazırlık", q:"Peygamberimiz “Hacda yapacağınız ibadetleri benden öğrenin...” buyurmuştur.\n\nBu söz aşağıdakilerden hangisini gösterir?", o:["Hac ibadetinin nasıl yapılacağını sünnetin açıkladığını","Hac ibadetinin Kur'an'da hiç geçmediğini","Haccın yalnızca Peygamberimizin döneminde farz olduğunu","Hacca giden herkesin Kur'an'ı ezberlemesi gerektiğini"], a:0,
     w:"Haccın farz olduğu Kur'an'da bildirilir; zamanı, şartları ve uygulanışı sünnetle belirlenmiştir. Peygamberimiz bu ibadeti bizzat yaparak göstermiştir."},
    {u:"EK · 1. Yazılı Hazırlık", q:"Kur'an'ın rehberliğinin hayatımızda ortaya çıkması için gereken adımlar hangi seçenekte doğru sırayla verilmiştir?", o:["Okumak → anlamak → yaşamak","Anlamak → yaşamak → okumak","Ezberlemek → yazmak → saklamak","Dinlemek → ezberlemek → saklamak"], a:0,
     w:"Önce okunur (okumak ibadettir), sonra ayetler üzerinde düşünülüp anlaşılır, en sonunda mesajı hayata geçirilir. En önemli adım yaşamaktır."},
    {u:"EK · 1. Yazılı Hazırlık", q:"Peygamberimiz “Sizin en hayırlınız, Kur'an'ı öğrenen ve öğretendir.” buyurmuştur.\n\nBu hadisten çıkarılabilecek sonuç hangisidir?", o:["Kur'an'ı öğrenmek ve öğretmek değerli bir davranıştır.","Kur'an'ı yalnızca yaşı büyük olanlar öğrenmelidir.","Kur'an'ı öğrenen kişinin başka bir şey öğrenmesine gerek yoktur.","Kur'an yalnızca öğretmenler tarafından okunmalıdır."], a:0,
     w:"Hadis, Kur'an'ı öğrenenleri ve öğretenleri “en hayırlı” sayar; yani bu iş çok değerlidir. Seçeneklerdeki “yalnızca” ve “gerek yoktur” gibi sınırlamalar hadiste yoktur."},
    {u:"EK · 1. Yazılı Hazırlık", q:"Kur'an'da “Namazları ve orta namazı aksatmadan kılın...” buyrulur. Peygamberimiz de “Orta namaz, ikindi namazıdır.” demiştir.\n\nBu örnek sünnetin hangi görevini gösterir?", o:["Kur'an'daki ifadeleri açıklayıp anlaşılmasını kolaylaştırmak","Kur'an'a yeni ibadetler eklemek","Kur'an ayetlerinin yazılmasını sağlamak","Önceki ilahi kitapları düzeltmek"], a:0,
     w:"Ayetteki “orta namaz” ifadesinin hangi namaz olduğu açık değildi; Peygamberimiz bunun ikindi namazı olduğunu söyleyerek açıkladı."},
    {u:"EK · 1. Yazılı Hazırlık", q:"Emre yemeğe besmeleyle başlar, tabağında yemek bırakmaz, sofrayı toplarken annesine yardım eder.\n\nEmre'nin bu davranışları en çok neyi gösterir?", o:["Peygamberimizin örnek davranışlarını hayatına taşıdığını","Kur'an'ı ezberlemeye çalıştığını","Zekât vermeye hazırlandığını","Yalnızca çevresindekilerin onu övmesini istediğini"], a:0,
     w:"Besmeleyle başlamak, israftan kaçınmak ve anne babaya iyilik etmek Peygamberimizin örnek davranışlarındandır."},

    {u:"EK · 1. Yazılı Hazırlık", q:"Kupkuru toprağın baharda rengârenk çiçeklerle donandığını gören bir öğrenci “Bu düzen kendiliğinden olamaz.” diyor.\n\nÖğrencinin bu düşüncesi “Niçin inanıyorum?” sorusuna hangi cevabı verir?", o:["Evrendeki düzen bir yaratıcının varlığını gösterir.","Doğadaki olayların hepsi tesadüfen olur.","İnsan yalnızca gözüyle gördüğüne inanmalıdır.","Bitkiler kendi kendini yaratır."], a:0,
     w:"“Allah'ın rahmetinin izlerine bir bak: Ölü toprağa nasıl can veriyor...” (Rum suresi 50). Evrendeki düzen tesadüf değildir; bir yaratıcıyı gösterir."},
    {u:"EK · 1. Yazılı Hazırlık", q:"Ameliyata girecek olan Elif, Allah'ın kendisini yalnız bırakmayacağına inandığı için korkusuna yenilmiyor, sakin ve umutlu kalabiliyor.\n\nBu durum inanmanın insana neyi kazandırdığını gösterir?", o:["Güven duygusu ve manevi dayanıklılık","Ameliyatın nasıl yapılacağına dair bilgi","Doktorlara ihtiyaç duymama düşüncesi","Başkalarından üstün olma duygusu"], a:0,
     w:"İnanmak insana yalnız olmadığını hissettirir; güven duygusu ve manevi dayanıklılık kazandırır, zor anda umudu korur. Öğretmenin dağcı sorusunun cevabı da budur."},
    {u:"EK · 1. Yazılı Hazırlık", q:"“... Biliniz ki kalpler ancak Allah'ı anmakla huzur bulur.” (Rad suresi 28)\n\nBu ayet inanmanın insana hangi katkısını anlatır?", o:["İç huzuru","Hiç üzülmeme","Herkesin sevgisi","Hastalıktan korunma"], a:0,
     w:"Ayet, kalbin huzurunu Allah'ı anmaya bağlar. İnanmak insana derin bir iç huzuru verir."},
    {u:"EK · 1. Yazılı Hazırlık", q:"“İman” kelimesinin sözlük anlamı aşağıdakilerden hangisidir?", o:["Güvenmek, şüphe duymadan kabullenmek, tasdik etmek","Teslim olmak, güven ve emniyet içinde bulunmak","Yol, âdet ve gidişat; insanın tuttuğu yol","Okumak, toplamak ve bir araya getirmek"], a:0,
     w:"İman: güvenmek, şüphesiz kabullenmek, tasdik etmek. “Teslim olmak, güven ve emniyette bulunmak” İslam kelimesinin, “yol, âdet, gidişat” sünnetin, “okumak, toplamak” Kur'an kelimesinin anlamıdır."},
    {u:"EK · 1. Yazılı Hazırlık", q:"İslam dinine göre imanın iki unsuru hangi seçenekte birlikte verilmiştir?", o:["Kalp ile tasdik etmek ve dil ile söylemek","Namaz kılmak ve oruç tutmak","Kur'an okumak ve ezberlemek","Hacca gitmek ve zekât vermek"], a:0,
     w:"İman, inanılması gerekenleri kalp ile tasdik edip dil ile söylemektir. Diğer seçeneklerdekiler ibadetlerdir; imanın unsurları değildir."},
    {u:"EK · 1. Yazılı Hazırlık", q:"İman ile salih amel arasındaki ilişki kitapta hangi benzetmeyle anlatılır?", o:["Bir ağacın kökü ile dalları","Bir binayı ayakta tutan sütunlar","Sabah aç çıkıp akşam tok dönen kuşlar","Baharda yeniden canlanan toprak"], a:0,
     w:"İman kök, salih ameller dallardır: kök sağlam olursa dallar canlı olur. İman güzel davranışlarla beslenip olgunlaşır."},
    {u:"EK · 1. Yazılı Hazırlık", q:"Amentü duasındaki “Ölümden sonra diriliş gerçektir.” ifadesi hangi inanç esasıyla ilgilidir?", o:["Ahiret gününe iman","Meleklere iman","Kitaplara iman","Peygamberlere iman"], a:0,
     w:"Ölümden sonra diriliş ve ebedî hayat ahiret inancının konusudur."},

    {u:"EK · 1. Yazılı Hazırlık", q:"Selin, Allah'ın var ve bir olduğuna, Hz. Muhammed'in de O'nun kulu ve elçisi olduğuna kalbiyle inanıyor ve bunu diliyle de söylüyor.\n\nSelin inanç bakımından hangi grupta yer alır?", o:["Mümin","Münafık","Kâfir","Hanif"], a:0,
     w:"Kalbiyle inanıp diliyle söyleyen kişi mümindir. Cevapta iki şartı da yaz: kalbiyle inanıyor ve diliyle söylüyor."},
    {u:"EK · 1. Yazılı Hazırlık", q:"Allah'ın varlığını ve birliğini, İslam'ın temel esaslarını reddettiğini açıkça söyleyen kişiye ne denir?", o:["Münafık","Kâfir","Mümin","Hanif"], a:1,
     w:"Kâfir gerçeği bile bile reddeder ve bunu açıkça söyler. Münafık ise inanmadığını gizler, “inanıyorum” der."},
    {u:"EK · 1. Yazılı Hazırlık", q:"Peygamberimiz münafığın üç alametini saymıştır. Aşağıdakilerden hangisi bunlardan biri DEĞİLDİR?", o:["Konuştuğunda yalan söylemek","Kendisine emanet edilene ihanet etmek","Söz verdiğinde sözünde durmamak","Hata yaptığında özür dilemek"], a:3,
     w:"Hadiste üç alamet sayılır: yalan söylemek, emanete ihanet etmek, sözünde durmamak. Hatayı kabul edip özür dilemek ise müminin güzel davranışıdır."},
    {u:"EK · 1. Yazılı Hazırlık", q:"Bir kişinin İslam dinine girdiğini ve mümin kimliğini ifade ettiği söz hangisidir?", o:["Kelimeişehadet","Besmele","Elhamdülillah","Selamünaleyküm"], a:0,
     w:"Kelimeişehadet (“Eşhedü ellâ ilâhe illallah ve eşhedü enne Muhammeden abdühû ve rasûlüh”) mümin olmanın anahtarıdır. Besmele işe başlarken, Elhamdülillah şükrederken, Selamünaleyküm selamlaşırken söylenir."},
    {u:"EK · 1. Yazılı Hazırlık", q:"Kitapta İslam'ın beş şartı, bir binayı ayakta tutan ana sütunlara benzetilir.\n\nBu benzetmeyle anlatılmak istenen nedir?", o:["Bu şartların İslam'ın temelini oluşturduğu","İslam'ın yalnızca ibadetlerden oluştuğu","Bu şartların yalnız büyükleri ilgilendirdiği","Şartlardan birini yerine getirmenin yeteceği"], a:0,
     w:"Sütunlar binayı ayakta tutar; İslam'ın beş şartı da İslam'ın temelini oluşturur, müminin ibadet hayatını ve ahlakını inşa eder."},
    {u:"EK · 1. Yazılı Hazırlık", q:"İbadetlerle müminin hayatına katkıları eşleştirilmiştir. Hangisi DOĞRUDUR?", o:["Namaz – zamanı planlı kullanma ve disiplin","Zekât – günde beş vakit Allah'ın huzuruna çıkma","Hac – ramazan ayı boyunca sabretmeyi öğrenme","Oruç – malın bir kısmını her yıl ihtiyaç sahibine verme"], a:0,
     w:"Beş vakit namaz zamanı planlı kullanmayı ve disiplini öğretir. Günde beş vakit Allah'ın huzuruna çıkmak namazdır, ramazan boyunca sabır oruçtur, malın bir kısmını vermek zekâttır."},
    {u:"EK · 1. Yazılı Hazırlık", q:"Teneffüste top oynarken sınıfın camını çatlatan Kaan, kimse görmemiş olmasına rağmen durumu öğretmenine anlatıyor.\n\nKaan'ın davranışı mümin kimliğinin hangi özelliklerini yansıtır?", o:["Dürüstlük ve sorumluluk","Cömertlik ve paylaşma","Sabır ve tevekkül","Temizlik ve düzen"], a:0,
     w:"Kimse görmese de doğruyu söylemek dürüstlük, yaptığının sonucunu üstlenmek sorumluluktur. Mümin ibadetlerini ahlakına da yansıtır."},
    {u:"EK · 1. Yazılı Hazırlık", q:"Peygamberimiz “Müminlerin iman bakımından en mükemmeli, ahlak bakımından en güzel olanıdır.” buyurmuştur.\n\nBu hadise göre iman ile ahlak arasındaki ilişki nedir?", o:["İman ile güzel ahlak birbirini tamamlar.","Güzel ahlak yalnızca ibadetle ilgilidir.","İman güçlendikçe ahlakın önemi azalır.","Ahlak, imandan bağımsız bir konudur."], a:0,
     w:"Hadis imanın olgunluğunu güzel ahlaka bağlar: iman ile güzel ahlak birbirini tamamlayan iki parçadır."},

    {u:"EK · 1. Yazılı Hazırlık", q:"“Esmayıhüsna” ne demektir?", o:["Allah'ın en güzel isimleri","Peygamberimizin sözleri","İslam'ın beş şartı","Kur'an'ın ilk ayetleri"], a:0,
     w:"Esma “isimler”, hüsna “en güzel” demektir. Peygamberimiz Allah'ın doksan dokuz ismi olduğunu bildirmiştir."},
    {u:"EK · 1. Yazılı Hazırlık", q:"Ahmet Amca tarlasını sürdü, tohumunu ekti, düzenli olarak suladı. Sonra “Ben üzerime düşeni yaptım, gerisini Rabbime bırakıyorum.” dedi.\n\nAhmet Amca'nın tutumu Allah'ın hangi ismiyle ilgilidir?", o:["Vekîl","Selam","Hâdi","Hamid"], a:0,
     w:"Önce çalışıp sonra sonucu Allah'a bırakmak tevekküldür; Vekîl ismiyle ilgilidir. Vekîl, işleri düzenleyen ve koruyup gözeten demektir."},
    {u:"EK · 1. Yazılı Hazırlık", q:"“Her türlü eksiklikten uzak olan, kullarına güvenlik, barış ve esenlik veren” anlamına gelen isim hangisidir?", o:["Vekîl","Hâdi","Selam","Şekur"], a:2,
     w:"Selam ismini bilen Müslüman selamlaşır, çevresine güven verir, kimseye zarar vermez."},
    {u:"EK · 1. Yazılı Hazırlık", q:"Namazın her rekâtında okunan Fatiha suresindeki “Bizi dosdoğru yola ilet.” duası Allah'ın en çok hangi ismiyle ilgilidir?", o:["Selam","Vekîl","Kerim","Hâdi"], a:3,
     w:"Hâdi doğru yolu gösteren demektir. Bu duayla Allah'tan hidayet isteriz ve bu isteği her rekâtta yenileriz."},
    {u:"EK · 1. Yazılı Hazırlık", q:"Müslümanların birbirine “Selamünaleyküm.” demesinin anlamı aşağıdakilerden hangisidir?", o:["Allah sana sağlık, afiyet ve esenlik versin.","Allah bize yeter, O ne güzel vekildir.","Allah'tan başka ilah yoktur, Muhammed O'nun elçisidir.","Bizi dosdoğru yola ilet."], a:0,
     w:"“Selamünaleyküm – Aleykümselam” karşılıklı bir duadır: selam veren de alan da karşısındakine sağlık, afiyet, esenlik, güven ve huzur diler."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Yusuf sabah namazını kıldı, kahvaltıdan sonra bahçeye fidan dikti, akşam da bir süre Kur'an okudu. Bunların hepsini Allah'ın rızası için yaptı.\n\nYusuf'un davranışlarıyla ilgili hangisi söylenebilir?", o:["Yalnızca vakti ve şartları belirli ibadetler yapmıştır.","Fidan dikmek ibadet sayılmaz, yalnızca bir doğa etkinliğidir.","Vakti belirli olan ve olmayan ibadetleri birlikte yapmıştır.","Yaptıklarından yalnızca namaz ibadet sayılabilir."], a:2,
     w:"Sabah namazının vakti ve şartları belirlenmiştir. Fidan dikmek ve Kur'an okumak ise belli bir vakte bağlı olmayan ibadetlerdendir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Sınavda başarılı olan Burak, “Bu başarıyı bana veren Rabbime teşekkür etmeliyim.” diyerek iki rekât nafile namaz kıldı.\n\nBurak'ın bu davranışı ibadetin hangi amacını en çok yansıtır?", o:["Arkadaşlarına örnek olmak","Allah'a şükretmek","Bedenini dinlendirmek","Öğretmeninin takdirini kazanmak"], a:1,
     w:"Burak başarısını Allah'ın bir lütfu olarak görüp O'na teşekkür etmek için namaz kılmıştır. İbadet, Rabbimize şükretmenin bir ifadesidir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Ali, arkadaşlarının ısrarına rağmen sınavda kopya çekmedi ve “Rabbim yapma dediği şeyden uzak durmamı istiyor.” dedi. Akşam da namazını vaktinde kıldı.\n\nAli'nin tutumu kitaptaki hangi açıklamaya uygundur?", o:["Kulluk, Allah'ın emirlerini yapıp yasaklarından uzak durmaktır.","Salih amel, yalnızca camide yapılan iyi işlerden oluşur.","İbadet, yalnızca ramazan ayında yapılması gereken işlerden ibarettir.","Rızık, insanın yalnızca kendi emeğiyle kazandığı şeylerdir."], a:0,
     w:"Kulluk, Allah'a itaat etmektir: O'nun “Yap!” dediklerini yapmak, “Yapma!” dediklerinden uzak durmak. Ali hem yasaktan kaçınarak hem namazını kılarak bunu göstermiştir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Zehra'nın ailesi ramazan ayında fitresini ihtiyaç sahibi bir aileye verdi. Kurban Bayramı'nda da kurban etinin bir bölümünü ihtiyaç sahibi komşularıyla paylaştı.\n\nBu ibadetlerin topluma katkısı hangisidir?", o:["Müslümanları günde beş vakit camide bir araya getirip kaynaştırır.","Farklı ülkelerden gelenleri Kâbe'de buluşturur.","Kişinin günahlarından arınıp temizlenmesini sağlar.","Zengin ile fakiri yakınlaştırıp dayanışmayı güçlendirir."], a:3,
     w:"Zekât, fitre ve kurban maddi imkânı iyi olanlarla ihtiyaç sahipleri arasında köprü olur. Dostluk ve kardeşlik gelişir, toplumda dayanışma güçlenir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"“Ben cinleri ve insanları, ancak bana ibadet etsinler diye yarattım.” (Zariyat suresi 56)\n\nBu ayetten hangi sonuç çıkarılabilir?", o:["İbadet yalnızca peygamberlerin bir görevidir.","İnsanın yaratılış amacı Allah'a kulluktur.","İbadetin şekli kişiye göre değişebilir.","Cinler ibadetle sorumlu tutulmamıştır."], a:1,
     w:"Ayet, Allah'ın cinleri ve insanları kendisine ibadet etmeleri için yarattığını bildirir. Yani insanın yaratılış amacı Rabbine kulluk etmektir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"“... De ki: Şüphesiz benim namazım da diğer ibadetlerim de yaşamam da ölümüm de âlemlerin Rabbi Allah içindir.” (Enam suresi 162)\n\nBu ayete göre bir Müslümanın ibadet anlayışı nasıl olmalıdır?", o:["İbadeti yalnızca belli günlere ve yerlere sınırlamalıdır.","Namaz dışındaki davranışlarını hiç dinle ilişkilendirmemelidir.","Hayatının tamamını Allah'ın rızasını gözeterek yaşamalıdır.","İbadete ancak yaşı ilerleyince önem vermelidir."], a:2,
     w:"Ayet, Müslümanın namazı ve diğer ibadetleri gibi yaşamını ve ölümünü de Allah'a adadığını bildirir. Bu bilinçle yaşayan kişi hayatını Allah'ın rızasına göre düzenler."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Ramazanda oruç tutan Deniz, okul çıkışı arkadaşları dondurma yerken canı çekse de iftara kadar bekledi ve orucunu bozmadı.\n\nBu durum orucun insana hangi kazanımını gösterir?", o:["Açlık ve susuzluğa karşı sabretmeyi","Düzenli ve planlı bir hayat sürmeyi","Malını ihtiyaç sahipleriyle paylaşmayı","Temizliği bir alışkanlık hâline getirmeyi"], a:0,
     w:"Kitaba göre oruç insana açlık ve susuzluğa karşı sabretmeyi öğretir. Deniz canı çekse de iftara kadar bekleyerek bu sabrı göstermiştir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"“Güzel davranışlarımızın ibadet değeri kazanması için her şeyden önce ... gerekir.”\n\nBoş bırakılan yere hangisi getirilmelidir?", o:["bunları herkese duyurmamız","Allah'a iman etmemiz","karşılığında övgü almamız","bunları yalnızca camide yapmamız"], a:1,
     w:"Kitaba göre iyi bir kul olmanın ilk şartı Allah'ın varlığına ve birliğine iman etmektir. İman olmadan yapılan iyilik ibadet değeri kazanmaz."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Ömer ramazanda bir gün çok meşgul olduğu için akşama kadar hiçbir şey yiyip içmedi. Ancak oruç tutmaya karar vermemişti, yalnızca yemeğe vakit bulamamıştı.\n\nÖmer'in aç kalmasının oruç sayılmaması ibadetin hangi ilkesiyle açıklanır?", o:["Sünnete uygunluk","İman","Cemaatle yapılma","Niyet"], a:3,
     w:"Oruç, ibadet niyetiyle yeme ve içmeden uzak durmaktır. Ömer oruç tutmaya karar vermediği için niyeti yoktur, niyetsiz yapılan ibadet de geçerli olmaz."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Kerem kalabalık bir camide de evinde tek başına da namazını aynı özenle kılar. Onun için önemli olan insanların ne düşündüğü değil, Allah'ın hoşnutluğudur.\n\nKerem'in tutumu ibadetin en çok hangi ilkesini yansıtır?", o:["İhlas","İman","Sünnete uygunluk","Tevekkül"], a:0,
     w:"İhlas, söz ve davranışlarda yalnız Allah'ın rızasını gözetmek, ibadeti gösterişten uzak ve içtenlikle yapmaktır. Kerem'in kimse görmese de aynı özeni göstermesi bunun örneğidir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Bir öğrenci sınıftaki tartışmada “Namazın rekât sayılarını herkes kendi işine göre azaltıp çoğaltabilir.” dedi.\n\nBu düşünce ibadetin hangi ilkesine aykırıdır?", o:["Niyet","Sünnete uygunluk","İhlas","Cemaatle kılınma"], a:1,
     w:"İbadetlerin vakti, şekli ve şartları Allah ve Peygamberimiz tarafından belirlenmiştir, kimse değiştiremez. Peygamberimiz namazı bizzat kılarak öğretmiştir, biz de onun öğrettiği gibi kılarız."},
    {u:"EK · 2. Yazılı Hazırlık", q:"İbadetin dört temel ilkesiyle ilgili hangisi doğrudur?", o:["Herhangi birine uymak, ibadetin kabulü için tek başına yeterlidir.","Yalnızca vakti ve şartları belirlenmiş ibadetlerde aranır.","Toplumun ihtiyacına göre zamanla değiştirilebilir.","Birbirini tamamlar, biri eksik olursa ibadet amacına ulaşmaz."], a:3,
     w:"Kitaba göre bu ilkeler birbirinin tamamlayıcısıdır. Biri eksik olduğunda ibadet amacına ulaşmaz."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Peygamberimiz “... Allah katında amellerin en sevimlisi, az da olsa devamlı olanıdır.” buyurmuştur.\n\nBu hadise en uygun davranış hangisidir?", o:["Yalnızca ramazan ayında uzun süre Kur'an okuyup sonra bırakmak","Her gün birkaç sayfa da olsa düzenli Kur'an okumak","Bir gün çok okuyup sonra haftalarca ara vermek","Sadece canı istediği günlerde Kur'an okumak"], a:1,
     w:"Hadis, az da olsa sürekli yapılan ibadetin Allah katında daha sevimli olduğunu bildirir. İbadetini düzenli sürdüren kişinin disiplin ve sorumluluk duygusu gelişir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Aşağıdakilerden hangisi kitapta sayılan ibadetin temel ilkelerinden biri DEĞİLDİR?", o:["Sünnete uygunluk","İhlas","Tevekkül","İman"], a:2,
     w:"Kitaba göre ibadetin temel ilkeleri iman, niyet, ihlas ve sünnete uygunluktur. Tevekkül ise üzerine düşeni yaptıktan sonra sonucu Allah'a bırakmaktır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Farz ve vacip ibadetler hangi yönden birbirine benzer?", o:["Yerine getirmeyen kişinin günah işlemiş olması","İkisinin de aynı açıklık ve kesinlikte emredilmiş olması","İnkâr eden kişinin dinden çıkmış sayılması","Peygamberimizin ara sıra yapıp terk etmesi"], a:0,
     w:"Kitaba göre farzı da vacibi de yerine getirmeyen günah işlemiş olur. Ancak farz Allah'ın kesin emridir, vacip ise farz kadar açık ve kesin değildir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Ramazan orucu tutmak, teravih namazı kılmak, fıtır sadakası vermek ve nafile oruç tutmak ibadetlerinin hükümleri bu sırayla hangi seçenekte doğru verilmiştir?", o:["Farz – vacip – sünnet – müstehap","Vacip – sünnet – farz – müstehap","Farz – sünnet – vacip – müstehap","Farz – sünnet – müstehap – vacip"], a:2,
     w:"Kitaba göre ramazan orucu farz, teravih namazı sünnet, fıtır sadakası vacip, nafile oruç ise müstehaptır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Sabah namazının sünneti ile ikindi namazının ilk sünneti karşılaştırıldığında hangisi doğrudur?", o:["Sabahın sünneti gayrimüekkede, ikindinin ilk sünneti müekkede sünnettir.","İkisi de Peygamberimizin hiç terk etmediği farz namazlardandır.","Sabahın sünneti vacip, ikindinin ilk sünneti ise müstehaptır.","Sabahın sünneti müekkede, ikindinin ilk sünneti gayrimüekkede sünnettir."], a:3,
     w:"Peygamberimizin devamlı kılıp nadiren terk ettiği sabah namazının sünneti müekkede, bazen kılıp bazen terk ettiği ikindinin ilk sünneti ise gayrimüekkede sünnettir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Farz ile müstehap hangi bakımdan birbirinden ayrılır?", o:["Allah'a yaklaştırıp yaklaştırmaması","Yapılmasının zorunlu olup olmaması","İbadet sayılıp sayılmaması","Müslümanlarca yapılıp yapılmaması"], a:1,
     w:"Farzı Allah kesin olarak emretmiştir, yapılması zorunludur. Müstehap ise yapılması hoş ve güzel karşılanan ama zorunlu tutulmayan ibadettir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Öğretmen sınıftan kısa bir süre çıktığında Emir, arkadaşının sınav kâğıdına bakmayı düşündü. Sonra “Kimse görmese de Rabbim beni görüyor.” diyerek vazgeçti.\n\nEmir'in bu tutumu Allah'ın hangi güzel ismini bildiğini gösterir?", o:["Rakib","Şekur","Hamid","Selam"], a:0,
     w:"Rakib, her şeyi daima gözetip koruyan demektir. Emir, Allah'ın kendisini her an gördüğünü bildiği için yanlıştan vazgeçmiştir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Hasta komşusunun market alışverişini yapan Elif, “Rabbim yaptığım iyiliğin karşılığını fazlasıyla verir.” diye düşündü.\n\nElif'in bu düşüncesi Allah'ın hangi güzel ismiyle ilgilidir?", o:["Rakib","Hamid","Şekur","Vekîl"], a:2,
     w:"Şekur, kullarının iyiliklerine bol karşılık veren demektir. Elif'in düşüncesi bu isme uygundur."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Gece gökyüzündeki sayısız yıldızı seyreden Defne, “Bu kusursuz düzeni yaratan Rabbim ne kadar övülse azdır.” dedi.\n\nDefne'nin bu sözü Allah'ın hangi güzel ismiyle ilgilidir?", o:["Rakib","Selam","Şekur","Hamid"], a:3,
     w:"Hamid, övgüye layık olan ve övülen demektir. Defne kâinattaki düzeni görüp Rabbinin övülmeye layık olduğunu dile getirmiştir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"“Elhamdülillah” sözünün anlamı aşağıdakilerden hangisidir?", o:["Her türlü övgü Allah'a mahsustur.","Allah'tan başka ilah yoktur.","Allah her şeyi gözetip korur.","Allah bize yeter, O ne güzel vekildir."], a:0,
     w:"Elhamdülillah sözüyle Müslüman bütün övgülerin yalnız Allah'a ait olduğunu dile getirir. Peygamberimiz, nimet karşısında böyle hamdetmenin o nimetten daha değerli olduğunu söylemiştir."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Allah'ın aklımızdan geçenleri, niyetimizi ve ibadetlerimizdeki samimiyeti de bildiğine inanan bir Müslüman nasıl davranır?", o:["İnsanların göremediği yerlerde kurallara uymayabilir.","İbadetlerini yalnızca başkaları görsün diye özenle yapar.","Davranışlarında ve ibadetlerinde içten ve özenli olur.","Yaptığı işlerin sorumluluğunu başkalarına yükler."], a:2,
     w:"Allah'tan hiçbir şey gizli kalmadığını bilen kişi her işinden sorumlu olduğunun farkındadır. Bu yüzden ibadetlerini aksatmaz, içtenlikle ve özenle yapmaya çalışır."},
    {u:"EK · 2. Yazılı Hazırlık", q:"Peygamberimiz, insanlar geçebilsin diye yoldaki bir engeli kaldırmanın ve susamış bir hayvana su vermenin Allah tarafından mükâfatlandırılacağını müjdelemiştir.\n\nBu müjdeden çıkarılabilecek sonuç hangisidir?", o:["Yalnızca büyük iyilikler Allah katında değerlidir.","Hayvanlara yapılan iyilikler ibadet sayılmaz.","İyiliklerin karşılığı yalnızca bu dünyada verilir.","Küçük görünen iyilikler de karşılıksız kalmaz."], a:3,
     w:"Hadis, insanlara ve hayvanlara yapılan küçük görünen iyiliklerin de ödüllendirileceğini bildirir. Allah iyiliğin büyüklüğüne bakmadan karşılığını verir."}
  ];
